import { IJsonParseResult, ILlmSchema } from "@typia/interface";
import { LlmJson } from "@typia/utils";

/**
 * Parse LLM output as JSON leniently and coerce it to the parameters schema.
 *
 * Schema coercion runs only after successful parsing. Failure diagnostics and
 * partial data pass through unchanged. The result is not validated; the type
 * argument is the caller's assertion.
 *
 * @evidence contracts/common.md#principled-implementation The function delegates to the utilities' lenient JSON parser, which recovers incomplete or malformed model output and coerces double-stringified values to the types that the parameters schema declares, and types the result as the caller's `T` without validating it.
 * @evidence contracts/common.md#clear-and-simple-design A one-line adapter so the emitted code depends on one internal name and the utility package remains the owner of the parser.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts There is no second parser to drift from the utility's.
 * @evidence contracts/common.md#meaningful-documentation The doc states lenient parsing, success-only coercion, unchanged failure diagnostics and that the type argument is the caller's unchecked assertion.
 */
export const _parseLlmArguments = <T>(
  input: string,
  parameters: ILlmSchema.IParameters,
): IJsonParseResult<T> => LlmJson.parse(input, parameters);

typia/src/internal/_plainCloneAny.ts:
import { Resolved } from "@typia/interface";

/**
 * Clone an untyped value into plain data.
 *
 * Arrays, sets, maps, dates, regular expressions, typed arrays, buffers, blobs,
 * files, boxed primitives and plain objects are rebuilt. Functions become
 * undefined; object properties with undefined results are omitted, while
 * arrays, sets and maps retain them. Weak collections throw. Cycles are not
 * tracked, and ordinary objects may invoke their own valueOf or property
 * getters.
 *
 * @evidence contracts/common.md#principled-implementation The clone walks the value and rebuilds arrays, sets, maps, boxed primitives, dates, regular expressions, typed arrays, buffers, data views, blobs, files and plain objects, turns functions into undefined, omits object properties whose cloned values are undefined while retaining such array/set/map results, and throws for weak collections. Native recognition checks intrinsic prototype accessors with `Reflect.apply` rather than trusting a supplied string tag or own getter; native clones use those captured accessors for their internal data. The ordinary-object branch invokes valueOf and clones its replacement when different, otherwise rebuilding enumerable own entries. Cycles are not tracked, so a cyclic value does not terminate.
 * @evidence contracts/common.md#clear-and-simple-design One entry function over a recognition function, a native cloner and a buffer range copier; the accessor captures are module-level constants because they are looked up once from the prototypes.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Recognition uses the intrinsic prototype accessors and no foreign method is replaced; native tags are checked through them and not by the forgeable string tag alone.
 * @evidence contracts/common.md#meaningful-documentation A comment states the cloned kinds, the object-member omission, retained container entries, observable valueOf/getters and the cycle limitation.
 */
export const _plainCloneAny = <T>(value: T): Resolved<T> =>
  cloneMain(value) as Resolved<T>;

const NOT_NATIVE = Symbol("not-native");
const objectToString = Object.prototype.toString;
const getter = (prototype: object, key: PropertyKey): (() => unknown) =>
  Object.getOwnPropertyDescriptor(prototype, key)!.get!;
const read = <T>(accessor: () => unknown, value: object): T =>
  Reflect.apply(accessor, value, []) as T;
const tryRead = <T>(
  accessor: (() => unknown) | undefined,
  value: object,
): { success: true; value: T } | { success: false } => {
  if (accessor === undefined) return { success: false };
  try {
    return { success: true, value: read<T>(accessor, value) };
  } catch {
    return { success: false };
  }
};

const arrayBufferByteLength = getter(ArrayBuffer.prototype, "byteLength");
const sharedArrayBufferByteLength =
  typeof SharedArrayBuffer === "undefined"
    ? undefined
    : getter(SharedArrayBuffer.prototype, "byteLength");
const dataViewBuffer = getter(DataView.prototype, "buffer");
const dataViewByteLength = getter(DataView.prototype, "byteLength");
const dataViewByteOffset = getter(DataView.prototype, "byteOffset");
const typedArrayName = getter(
  Object.getPrototypeOf(Uint8Array.prototype),
  Symbol.toStringTag,
);
const blobSize =
  typeof Blob === "undefined" ? undefined : getter(Blob.prototype, "size");
const blobType =
  typeof Blob === "undefined" ? undefined : getter(Blob.prototype, "type");
const fileName =
  typeof File === "undefined" ? undefined : getter(File.prototype, "name");
const fileLastModified =
  typeof File === "undefined"
    ? undefined
    : getter(File.prototype, "lastModified");
const regexpSource = getter(RegExp.prototype, "source");
const regexpFlags = getter(RegExp.prototype, "flags");

const nativeTag = (value: object): string | undefined => {
  let tagged: boolean;
  try {
    tagged = Symbol.toStringTag in value;
  } catch {
    return undefined;
  }
  if (!tagged)
    try {
      return objectToString.call(value);
    } catch {
      return undefined;
    }

  const date = tryRead<number>(Date.prototype.getTime, value);
  if (date.success) return "[object Date]";
  const typed = tryRead<string>(typedArrayName, value);
  if (typed.success && typed.value !== undefined)
    return `[object ${typed.value}]`;
  if (tryRead<number>(arrayBufferByteLength, value).success)
    return "[object ArrayBuffer]";
  if (tryRead<number>(sharedArrayBufferByteLength, value).success)
    return "[object SharedArrayBuffer]";
  if (tryRead<ArrayBufferLike>(dataViewBuffer, value).success)
    return "[object DataView]";
  if (tryRead<string>(fileName, value).success) return "[object File]";
  if (tryRead<number>(blobSize, value).success) return "[object Blob]";
  if (tryRead<string>(regexpSource, value).success) return "[object RegExp]";
  return undefined;
};

const cloneMain = (value: any): any => {
  if (value === undefined) return undefined;
  else if (typeof value === "object")
    if (value === null) return null;
    else if (Array.isArray(value)) return value.map(cloneMain);
    else {
      const native: any | typeof NOT_NATIVE = cloneNative(value);
      if (native !== NOT_NATIVE) return native;
      else if (value instanceof Set) return new Set([...value].map(cloneMain));
      else if (value instanceof Map)
        return new Map(
          [...value].map(([k, v]) => [cloneMain(k), cloneMain(v)]),
        );
      else if (value instanceof WeakSet || value instanceof WeakMap)
        throw new Error("WeakSet and WeakMap are not supported");
      else {
        const primitive: unknown = value.valueOf();
        if (primitive !== value) return cloneMain(primitive);
        return Object.fromEntries(
          Object.entries(value)
            .map(([k, v]) => [k, cloneMain(v)])
            .filter(([, v]) => v !== undefined),
        );
      }
    }
  else if (typeof value === "function") return undefined;
  return value;
};

const cloneNative = (value: object): any | typeof NOT_NATIVE => {
  const tag: string | undefined = nativeTag(value);
  switch (tag) {
    case "[object Date]": {
      const time = tryRead<number>(Date.prototype.getTime, value);
      return time.success ? new Date(time.value) : NOT_NATIVE;
    }
    case "[object Uint8Array]":
      return new Uint8Array(value as ArrayLike<number>);
    case "[object Uint8ClampedArray]":
      return new Uint8ClampedArray(value as ArrayLike<number>);
    case "[object Uint16Array]":
      return new Uint16Array(value as ArrayLike<number>);
    case "[object Uint32Array]":
      return new Uint32Array(value as ArrayLike<number>);
    case "[object BigUint64Array]":
      return new BigUint64Array(value as ArrayLike<bigint>);
    case "[object Int8Array]":
      return new Int8Array(value as ArrayLike<number>);
    case "[object Int16Array]":
      return new Int16Array(value as ArrayLike<number>);
    case "[object Int32Array]":
      return new Int32Array(value as ArrayLike<number>);
    case "[object BigInt64Array]":
      return new BigInt64Array(value as ArrayLike<bigint>);
    case "[object Float32Array]":
      return new Float32Array(value as ArrayLike<number>);
    case "[object Float64Array]":
      return new Float64Array(value as ArrayLike<number>);
    case "[object ArrayBuffer]": {
      const byteLength = tryRead<number>(arrayBufferByteLength, value);
      return byteLength.success
        ? cloneBufferRange(value as ArrayBuffer, 0, byteLength.value, false)
        : NOT_NATIVE;
    }
    case "[object SharedArrayBuffer]": {
      const byteLength = tryRead<number>(sharedArrayBufferByteLength, value);
      return byteLength.success
        ? cloneBufferRange(
            value as SharedArrayBuffer,
            0,
            byteLength.value,
            true,
          )
        : NOT_NATIVE;
    }
    case "[object DataView]": {
      const buffer = tryRead<ArrayBufferLike>(dataViewBuffer, value);
      if (!buffer.success) return NOT_NATIVE;
      const byteOffset: number = read(dataViewByteOffset, value);
      const byteLength: number = read(dataViewByteLength, value);
      return new DataView(
        cloneBufferRange(buffer.value, byteOffset, byteLength),
      );
    }
    case "[object File]": {
      const size = tryRead<number>(blobSize, value);
      if (
        typeof File === "undefined" ||
        !size.success ||
        blobType === undefined ||
        fileName === undefined ||
        fileLastModified === undefined
      )
        return NOT_NATIVE;
      return new File([value as Blob], read<string>(fileName, value), {
        type: read<string>(blobType, value),
        lastModified: read<number>(fileLastModified, value),
      });
    }
    case "[object Blob]": {
      const size = tryRead<number>(blobSize, value);
      if (
        typeof Blob === "undefined" ||
        !size.success ||
        blobType === undefined
      )
        return NOT_NATIVE;
      return new Blob([value as Blob], {
        type: read<string>(blobType, value),
      });
    }
    case "[object RegExp]": {
      const source = tryRead<string>(regexpSource, value);
      return source.success
        ? new RegExp(source.value, read<string>(regexpFlags, value))
        : NOT_NATIVE;
    }
    default:
      return NOT_NATIVE;
  }
};

const cloneBufferRange = (
  input: ArrayBufferLike,
  byteOffset: number,
  byteLength: number,
  shared?: boolean,
): ArrayBuffer | SharedArrayBuffer => {
  if (shared === undefined)
    shared = tryRead<number>(sharedArrayBufferByteLength, input).success;
  let output: ArrayBuffer | SharedArrayBuffer;
  if (shared) {
    if (typeof SharedArrayBuffer === "undefined")
      throw new TypeError("SharedArrayBuffer is not available");
    output = new SharedArrayBuffer(byteLength);
  } else {
    read<number>(arrayBufferByteLength, input);
    output = new ArrayBuffer(byteLength);
  }
  new Uint8Array(output).set(new Uint8Array(input, byteOffset, byteLength));
  return output;
};

typia/src/internal/_randomArray.ts:
import type { OpenApi } from "@typia/interface";

import { _isUniqueItems } from "./_isUniqueItems";
import { _randomInteger } from "./_randomInteger";

const DEFAULT_MIN_ITEMS = 1;
const DEFAULT_RANGE = 5;
const DEFAULT_RECURSIVE_RANGE = 2;

/**
 * Consecutive duplicates that end a unique draw once its floor is satisfied.
 *
 * For independent uniform draws with one unseen value among four, sixty-four
 * misses in a row have probability `0.75 ** 64`. This stopping rule does not
 * prove domain exhaustion. Below the floor it is disabled, but the total
 * attempt budget can still end before a reachable minimum is observed.
 */
const STALE_LIMIT = 64;

/**
 * Generate a random array from an array schema.
 *
 * The length is drawn between the bounds, with a default minimum of one, or
 * zero on a recursive cycle. For a unique array the count is a preference above
 * the minimum: drawing stops at the total attempt budget or, after reaching the
 * minimum, a run of duplicates. A result below the minimum throws even when
 * enough distinct values exist but were not observed within that budget.
 *
 * The optional source supplies draws in [0, 1); it defaults to the platform
 * source resolved when this helper is called. Nested draws use the same
 * source.
 *
 * @evidence contracts/common.md#principled-implementation The length is drawn between the schema's bounds with a default minimum of one, or zero on a recursive cycle so graph-shaped data ends, and elements come from the supplied callback. Unique generation stops at the requested count, count * 100 + 1000 total attempts, or sixty-four consecutive duplicates after the minimum is met. These bounded observations do not prove domain exhaustion; a result below the minimum throws even if the callback could produce more distinct values. A returned result always meets the minimum, while the chosen count is a preference above it.
 * @evidence contracts/common.md#clear-and-simple-design One function with a plain branch and a unique branch; defaults are module constants.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The unique branch accepts a result shorter than the preferred count when it meets the minimum. Failure means the minimum was not observed within the finite attempt budget, rather than proving it unreachable; no callback domain is inferred from repeated duplicates.
 * @evidence contracts/common.md#meaningful-documentation The doc states the length rule, the unique-draw budget and the stale limit, and the module comments explain the reasoning.
 */
export const _randomArray = <T>(
  props: Omit<OpenApi.IJsonSchema.IArray, "items"> & {
    element: (index: number, count: number) => T;
    recursive?: boolean;
  },
  source: () => number = Math.random,
) => {
  const defaultMinimum: number =
    props.recursive === true ? 0 : DEFAULT_MIN_ITEMS;
  const minimum: number =
    props.minItems ??
    Math.min(props.maxItems ?? defaultMinimum, defaultMinimum);
  const count: number = _randomInteger(
    {
      type: "integer",
      minimum,
      maximum:
        props.maxItems ??
        minimum +
          (props.recursive === true ? DEFAULT_RECURSIVE_RANGE : DEFAULT_RANGE),
    },
    source,
  );
  if (props.uniqueItems !== true)
    return new Array(count).fill(null).map((_, i) => props.element(i, count));
  // How many distinct values the element can take is not knowable from here --
  // `element` is a closure over whatever the transform emitted, from `boolean`
  // to a recursive object -- so the count above is a preference, not a
  // contract. Stop at the bounded attempt budget or duplicate-run limit, then
  // keep what was reached if it meets the minimum. Neither limit proves that
  // the callback's domain has nothing new left.
  //
  // Failing on that budget instead is what made `Array<boolean> &
  // UniqueItems` throw on two draws in three: `[true, false]` satisfies the
  // declaration at every count, and a count of five is unreachable for a
  // domain of two however many times it is redrawn. Only a result below the
  // floor is a real failure, which is still the honest outcome for a window
  // like `MinItems<3>` over a domain of two.
  //
  // Below the floor the whole budget is available, though a rare or biased
  // callback can still miss enough distinct values before it ends. Above the
  // floor further attempts only increase length, so `STALE_LIMIT` consecutive
  // duplicates end that search early. This bounds repeated work for nested
  // small-domain unique arrays without claiming the domain is exhausted.
  const elements: T[] = [];
  const maximumAttempts: number = count * 100 + 1000;
  let stale: number = 0;
  for (
    let attempts = 0;
    elements.length !== count && attempts !== maximumAttempts;
    attempts++
  ) {
    const candidate: T = props.element(elements.length, count);
    if (elements.every((element) => _isUniqueItems([element, candidate]))) {
      elements.push(candidate);
      stale = 0;
    } else if (elements.length >= minimum && ++stale === STALE_LIMIT) break;
  }
  if (elements.length < minimum)
    throw new Error(
      "Unable to generate enough unique items; the element domain may be too small.",
    );
  return elements;
};

typia/src/internal/_randomBigint.ts:
import { OpenApi } from "@typia/interface";

import { _decimalIntegerStep } from "./_decimal";

/**
 * Generates a random `bigint` satisfying an integer schema.
 *
 * The schema carries its bounds and step as numbers, but the value is a
 * `bigint`, so the draw runs on integers. Drawing through doubles rounded every
 * value past 2^53, and it checked `multipleOf` against a double's shortest
 * decimal text rather than the integer `BigInt` makes of it, so `random`
 * returned values the validator rejects, or gave up on a range that holds one
 * (#2457). An integral bound or step is read as the integer the double holds,
 * which is the integer the validator compares with.
 *
 * @evidence contracts/common.md#principled-implementation Bounds and step are read as the integers their doubles hold, an exclusive bound is moved to the next inclusive integer, and the draw is made on bigints so no precision is lost past 2^53; a multiple of the step is chosen by dividing the range by the step, drawing a quotient and multiplying back. The draw scales one 53-bit sample, so a range wider than 2^53 values is sampled at most that many distinct points.
 * @evidence contracts/common.md#clear-and-simple-design One function with small private helpers for the bound, the step, the rounding divisions and the draw.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Errors for empty or infinite ranges are explicit, and the step is the integer the validator compares with.
 * @evidence contracts/common.md#meaningful-documentation The doc explains why the draw is not done through doubles and cites the issue.
 */
export const _randomBigint = (schema: OpenApi.IJsonSchema.IInteger): bigint => {
  const lower: bigint | null = boundary(
    schema.minimum,
    schema.exclusiveMinimum,
    "lower",
  );
  const upper: bigint | null = boundary(
    schema.maximum,
    schema.exclusiveMaximum,
    "upper",
  );
  const minimum: bigint =
    lower ?? (upper === null ? BigInt(0) : upper - BigInt(100));
  const maximum: bigint =
    upper ?? (lower === null ? BigInt(100) : lower + BigInt(100));
  if (minimum > maximum)
    throw new Error("Minimum value is greater than maximum value.");
  if (schema.multipleOf === undefined) return between(minimum, maximum);

  const step: bigint | null = integerStep(schema.multipleOf);
  if (step === null || step <= BigInt(0))
    throw new Error("The multipleOf value must be a positive finite number.");
  const first: bigint = ceilDivide(minimum, step);
  const last: bigint = floorDivide(maximum, step);
  if (first > last)
    throw new Error("The range does not contain a multipleOf value.");
  return between(first, last) * step;
};

/**
 * Reads one side's inclusive integer bound.
 *
 * `-Infinity` below or `Infinity` above excludes no integer, so it is no bound
 * at all; `Infinity` below or `-Infinity` above excludes every integer.
 */
const boundary = (
  inclusive: number | undefined,
  exclusive: number | undefined,
  side: "lower" | "upper",
): bigint | null => {
  const candidates: bigint[] = [];
  for (const [value, open] of [
    [inclusive, false],
    [exclusive, true],
  ] as const) {
    if (value === undefined) continue;
    if (Number.isFinite(value) === false) {
      if (value === (side === "lower" ? -Infinity : Infinity)) continue;
      throw new Error("Numeric range has no finite value.");
    }
    candidates.push(
      side === "lower"
        ? open
          ? BigInt(Math.floor(value)) + BigInt(1)
          : BigInt(Math.ceil(value))
        : open
          ? BigInt(Math.ceil(value)) - BigInt(1)
          : BigInt(Math.floor(value)),
    );
  }
  if (candidates.length === 0) return null;
  return candidates.reduce((x, y) =>
    side === "lower" ? (x > y ? x : y) : x < y ? x : y,
  );
};

/**
 * The smallest positive integer a `multipleOf` divides.
 *
 * An integral step is the integer its double holds; a fractional one, such as
 * `1.5`, steps by its smallest integer multiple (`3`).
 */
const integerStep = (multipleOf: number): bigint | null => {
  if (Number.isFinite(multipleOf) === false) return null;
  if (Number.isInteger(multipleOf)) return BigInt(multipleOf);
  return _decimalIntegerStep(multipleOf)?.coefficient ?? null;
};

const ceilDivide = (x: bigint, y: bigint): bigint => {
  const quotient: bigint = x / y;
  return x % y > BigInt(0) ? quotient + BigInt(1) : quotient;
};

const floorDivide = (x: bigint, y: bigint): bigint => {
  const quotient: bigint = x / y;
  return x % y < BigInt(0) ? quotient - BigInt(1) : quotient;
};

/** Draws an integer in `[minimum, maximum]`, scaling one 53-bit sample. */
const between = (minimum: bigint, maximum: bigint): bigint => {
  const scale: bigint = BigInt(1) << BigInt(53);
  const sample: bigint = BigInt(
    Math.min(
      Number(scale - BigInt(1)),
      Math.floor(Math.max(0, Math.random()) * Number(scale)),
    ),
  );
  return minimum + ((maximum - minimum + BigInt(1)) * sample) / scale;
};

typia/src/internal/_randomFormatByte.ts:
import { _randomInteger } from "./_randomInteger";
import {
  _ILengthProps,
  _RANDOM_LENGTH_ERROR,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomBase64 } from "./private/__randomComposition";

/**
 * Generate a Base64 string for the `byte` format at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation Base64 lengths are multiples of four, so an unconstrained draw spends four to twelve groups, and a constrained one raises the window floor to the first multiple of four it contains and steps by four; an empty window throws. Each character is from the alphabet that the validator allows, so no encoding step is needed and no padding is produced.
 * @evidence contracts/common.md#clear-and-simple-design One function over the shared length window and Base64 helpers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rule is the format's.
 * @evidence contracts/common.md#meaningful-documentation An inline comment explains the grouping.
 */
export const _randomFormatByte = (props?: _ILengthProps): string => {
  // Base64 encodes three bytes as four characters, so a valid length is always
  // a multiple of four; an unconstrained draw spends between four and twelve
  // groups, and a constrained one raises the window to the first multiple it
  // contains and steps by four from there.
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return __randomBase64(
      4 *
        _randomInteger({
          type: "integer",
          minimum: DEFAULT_GROUP_MIN,
          maximum: DEFAULT_GROUP_MAX,
        }),
    );
  const window = _randomLengthWindow(props, { minimum: 0, spread: 16 });
  const low: number = Math.ceil(window.low / 4) * 4;
  if (low > window.high) throw new Error(_RANDOM_LENGTH_ERROR);
  const length: number =
    low +
    4 *
      _randomLengthPick({
        low: 0,
        high: Math.floor((window.high - low) / 4),
      });
  return __randomBase64(length);
};

const DEFAULT_GROUP_MIN = 4;
const DEFAULT_GROUP_MAX = 12;

typia/src/internal/_randomFormatDate.ts:
import { _ILengthProps, _randomFormatLength } from "./_randomStringLength";
import { __IEpochProps, __randomEpoch } from "./private/__randomEpoch";

/**
 * Generate a `YYYY-MM-DD` date within the epoch bounds. Custom bounds must
 * describe valid Date instants with four-digit ISO years; expanded-year ISO
 * text is outside this fixed-width generator's contract.
 *
 * @evidence contracts/common.md#principled-implementation With valid Date bounds in the four-digit ISO-year range, a date is the first ten characters of a random instant's ISO text; the fixed-length wrapper checks it against the length bounds and throws when no draw fits. Custom out-of-range instants and expanded ISO years are not normalized here.
 * @evidence contracts/common.md#clear-and-simple-design One expression over the epoch drawer and the fixed-length wrapper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The instant bounds are handled by the shared epoch drawer.
 * @evidence contracts/common.md#meaningful-documentation The doc states that the date is the date part of a random instant within the epoch bounds.
 */
export const _randomFormatDate = (props?: __IEpochProps & _ILengthProps) =>
  _randomFormatLength(props, () =>
    new Date(__randomEpoch(props)).toISOString().substring(0, 10),
  );

typia/src/internal/_randomFormatDatetime:
import {
  _ILengthProps,
  _RANDOM_LENGTH_ERROR,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomDigits } from "./private/__randomComposition";
import { __IEpochProps, __randomEpoch } from "./private/__randomEpoch";

/**
 * Generate an RFC 3339 date-time with a `Z` offset at a length the bounds
 * allow. Custom epoch bounds must stay within valid Date instants with
 * four-digit ISO years, which the fixed-width second-precision prefix assumes.
 *
 * @evidence contracts/common.md#principled-implementation Within valid Date bounds with four-digit ISO years, an unconstrained draw is a random instant in ISO text; a constrained one keeps the fixed-width second-precision prefix and chooses either a `Z` suffix or a fraction of the digits needed, avoiding length21 and throwing when the window holds no valid length. Custom expanded-year bounds are outside this fixed-width contract.
 * @evidence contracts/common.md#clear-and-simple-design One function over the length window and digit helpers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rules are those of RFC 3339 timestamps with a `Z` offset.
 * @evidence contracts/common.md#meaningful-documentation The inline comments explain the length arithmetic.
 */
export const _randomFormatDatetime = (
  props?: __IEpochProps & _ILengthProps,
) => {
  const instant = (): string => new Date(__randomEpoch(props)).toISOString();
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return instant();
  // `YYYY-MM-DDTHH:MM:SS` plus `Z` is the shortest instant, and a fractional
  // second grows it one digit at a time. Because that fraction needs both a dot
  // and at least one digit, 21 is the single length between the two forms that
  // no instant can have.
  const window = _randomLengthWindow(props, {
    minimum: SECONDS + 1,
    spread: 8,
  });
  let length: number = _randomLengthPick(window);
  if (length === SECONDS + 2)
    length = window.high >= SECONDS + 3 ? SECONDS + 3 : SECONDS + 1;
  if (length < window.low || length > window.high)
    throw new Error(_RANDOM_LENGTH_ERROR);
  const base: string = instant().substring(0, SECONDS);
  return length === SECONDS + 1
    ? `${base}Z`
    : `${base}.${__randomDigits(length - SECONDS - 2)}Z`;
};

const SECONDS = "0000-00-00T00:00:00".length;

typia/src/internal/_randomFormatDuration:
import { _randomInteger } from "./_randomInteger";
import {
  _ILengthProps,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomNumeric } from "./private/__randomComposition";

/**
 * Generate an ISO 8601 duration at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation An unconstrained draw composes years, months and days and hours, minutes and seconds with zero parts omitted, and falls back to `PT0S`; a constrained one writes a single year designator with the digit count that fits, since an integer has no maximum digits, so any length from three upward is reachable.
 * @evidence contracts/common.md#clear-and-simple-design One function with two branches and a small composer.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rule follows the grammar and no length is redrawn blindly.
 * @evidence contracts/common.md#meaningful-documentation An inline comment explains the single designator.
 */
export const _randomFormatDuration = (props?: _ILengthProps): string => {
  if (props?.minLength === undefined && props?.maxLength === undefined) {
    const period: string = durate([
      ["Y", random(0, 100)],
      ["M", random(0, 12)],
      ["D", random(0, 31)],
    ]);
    const time: string = durate([
      ["H", random(0, 24)],
      ["M", random(0, 60)],
      ["S", random(0, 60)],
    ]);
    if (period.length + time.length === 0) return "PT0S";
    return `P${period}${time.length ? "T" : ""}${time}`;
  }
  // A single designator carries an unbounded digit count, so `P<n>Y` expresses
  // every length from three upward and `P1Y` is the shortest duration there is.
  const length: number = _randomLengthPick(
    _randomLengthWindow(props, { minimum: MINIMUM, spread: 6 }),
  );
  return `P${__randomNumeric(length - MINIMUM + 1)}Y`;
};

const MINIMUM = "P1Y".length;

const durate = (elements: [string, number][]) =>
  elements
    .filter(([_unit, value]) => value !== 0)
    .map(([unit, value]) => `${value}${unit}`)
    .join("");
const random = (minimum: number, maximum: number) =>
  _randomInteger({
    type: "integer",
    minimum,
    maximum,
  });

typia/src/internal/_randomFormatEmail.ts:
import { _randomString } from "./_randomString";
import { _ILengthProps, _randomSegmentLength } from "./_randomStringLength";

/**
 * Generate an email address at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation An unconstrained draw is a local part, a domain and a top-level label of random letters; a constrained one lets the local part absorb the length beside a fixed `@x.y` shape, and throws when the window is below that shape.
 * @evidence contracts/common.md#clear-and-simple-design One function over the segment-length helper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The shape is the generator's and its limits are reported.
 * @evidence contracts/common.md#meaningful-documentation An inline comment explains the fixed overhead.
 */
export const _randomFormatEmail = (props?: _ILengthProps): string => {
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return `${random(10)}@${random(10)}.${random(3)}`;
  // `<local>@<domain>.<tld>`: the local part absorbs the requested length while
  // a one-character domain and tld keep the fixed overhead (`@`, `.`) minimal.
  return `${_randomSegmentLength(props, 4, 10, 1)}@${random(1)}.${random(1)}`;
};

const random = (length: number) =>
  _randomString({
    type: "string",
    minLength: length,
    maxLength: length,
  });

typia/src/internal/_randomFormatHostname:
import { _randomInteger } from "./_randomInteger";
import { _randomString } from "./_randomString";
import { _ILengthProps } from "./_randomStringLength";

/**
 * Generate a hostname at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation A hostname is dot-joined labels of one to 63 characters, at most 253 in total, so the requested total is realized by splitting it into full labels and a remainder, never making a label longer than 63; an impossible window throws.
 * @evidence contracts/common.md#clear-and-simple-design One function, with the label builder exported because the internationalized variant shares it.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The limits are those of the hostname grammar.
 * @evidence contracts/common.md#meaningful-documentation Inline comments and the label builder's doc explain the split.
 */
export const _randomFormatHostname = (props?: _ILengthProps): string => {
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return `${random(10)}.${random(3)}`;
  // A hostname is dot-joined labels of 1..63 chars whose total is capped at 253,
  // so the requested length is realized by splitting it across enough labels.
  return _randomHostnameLabels(pickLength(props));
};

const MAX_TOTAL = 253;
const MAX_LABEL = 63;

const pickLength = (props: _ILengthProps): number => {
  let low: number = props.minLength === undefined ? 1 : props.minLength;
  if (low < 1) low = 1;
  const high: number =
    props.maxLength === undefined
      ? Math.min(MAX_TOTAL, low + 14)
      : Math.min(MAX_TOTAL, props.maxLength);
  if (high < low)
    throw new Error(
      "unable to generate a random hostname satisfying both the format and the length constraints.",
    );
  return _randomInteger({ type: "integer", minimum: low, maximum: high });
};

/**
 * Builds dot-joined hostname labels totaling exactly `length` characters, each
 * label within 63 chars. Shared with the idn-hostname generator, which realizes
 * its length the same way since #2317 gave the two formats one structure. The
 * callers supply an integer total from1 through253.
 *
 * @evidence contracts/common.md#principled-implementation A target length is spent as full 63-character labels with joining dots and a final label, with the one awkward remainder of 64 split into two labels so no label exceeds 63.
 * @evidence contracts/common.md#clear-and-simple-design One function shared by the hostname and idn hostname generators.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The splitting rule is the grammar's.
 * @evidence contracts/common.md#meaningful-documentation The doc states the total length and the label limit.
 */
export const _randomHostnameLabels = (length: number): string => {
  const parts: string[] = [];
  let remaining: number = length;
  while (remaining > MAX_LABEL + 1) {
    // one full label plus its joining dot
    parts.push(random(MAX_LABEL));
    remaining -= MAX_LABEL + 1;
  }
  if (remaining <= MAX_LABEL) parts.push(random(remaining));
  else {
    // remaining === MAX_LABEL + 1: two labels keep every label within 63 chars
    parts.push(random(MAX_LABEL - 1));
    parts.push(random(1));
  }
  return parts.join(".");
};

const random = (length: number) =>
  _randomString({ type: "string", minLength: length, maxLength: length });

