import { OpenApi } from "@typia/interface";

import { _randomMultiple } from "./_randomMultiple";

/**
 * Generate a random integer from an integer schema.
 *
 * Bounds are tightened to the integers they contain, a missing side defaults to
 * a window of one hundred beside the other, and a step is satisfied through the
 * decimal multiple generator.
 *
 * The optional source supplies draws in [0, 1); it defaults to the platform
 * source resolved when this helper is called. Nested draws use the same
 * source.
 *
 * @evidence contracts/common.md#principled-implementation The bounds are tightened to the integers they contain, an exclusive bound moves to the next representable integer, a missing side defaults to a window of one hundred around the other, an infinite bound that excludes nothing is dropped and one that excludes everything throws; the scalar draw maps the source fraction with floor(source() * (maximum - minimum + 1)) + minimum when the width is finite, or weighted finite endpoints otherwise, and clamps rounding to the selected bounds, or selects a multiple through the decimal multiple generator. Uniform index probabilities on exactly representable integer intervals require a uniform source; intervals beyond exact integer precision can return only representable numbers. An injected deterministic source retains the same bound arithmetic.
 * @evidence contracts/common.md#clear-and-simple-design One function with private boundary helpers shared in shape with the number generator.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Errors are explicit, and the default window of one hundred is an arbitrary generator choice that is documented by its use only.
 * @evidence contracts/common.md#meaningful-documentation The doc states how the bounds, the missing side and the step are handled, and the boundary helper explains the infinite bound rule.
 */
export const _randomInteger = (
  schema: OpenApi.IJsonSchema.IInteger,
  source: () => number = Math.random,
): number => {
  const lower: IBoundary | null = getLowerBoundary(schema);
  const upper: IBoundary | null = getUpperBoundary(schema);
  const minimum: number =
    lower?.value ?? (upper === null ? 0 : upper.value - 100);
  const maximum: number =
    upper?.value ?? (lower === null ? 100 : lower.value + 100);
  if (minimum > maximum)
    throw new Error("Minimum value is greater than maximum value.");
  return schema.multipleOf === undefined
    ? scalar({ minimum, maximum }, source)
    : _randomMultiple(
        {
          minimum,
          maximum,
          multipleOf: schema.multipleOf,
          exclusiveMinimum: lower?.exclusive ?? false,
          exclusiveMaximum: upper?.exclusive ?? false,
          integer: true,
        },
        source,
      );
};

const scalar = (
  props: { minimum: number; maximum: number },
  source: () => number,
): number => {
  const minimum: number = Math.ceil(props.minimum);
  const maximum: number = Math.floor(props.maximum);
  if (minimum > maximum) throw new Error("The integer range is empty.");
  if (!Number.isFinite(minimum) || !Number.isFinite(maximum))
    throw new Error("The integer range has no finite value.");
  const draw: number = source();
  const width: number = maximum - minimum + 1;
  const value: number = Number.isFinite(width)
    ? Math.floor(draw * width) + minimum
    : Math.floor((1 - draw) * minimum + draw * maximum);
  return Math.max(minimum, Math.min(maximum, value));
};

const getLowerBoundary = (
  schema: OpenApi.IJsonSchema.IInteger,
): IBoundary | null => {
  const inclusive: IBoundary | null = boundary(schema.minimum, false, "lower");
  const exclusive: IBoundary | null = boundary(
    schema.exclusiveMinimum,
    true,
    "lower",
  );
  const selected: IBoundary | null = selectBoundary(
    inclusive,
    exclusive,
    Math.max,
  );
  if (selected === null) return null;
  const integer: number = selected.exclusive
    ? Math.floor(selected.value) + 1
    : Math.ceil(selected.value);
  return {
    value:
      selected.exclusive && integer <= selected.value
        ? nextRepresentable(selected.value, true)
        : integer,
    exclusive: false,
  };
};

const getUpperBoundary = (
  schema: OpenApi.IJsonSchema.IInteger,
): IBoundary | null => {
  const inclusive: IBoundary | null = boundary(schema.maximum, false, "upper");
  const exclusive: IBoundary | null = boundary(
    schema.exclusiveMaximum,
    true,
    "upper",
  );
  const selected: IBoundary | null = selectBoundary(
    inclusive,
    exclusive,
    Math.min,
  );
  if (selected === null) return null;
  const integer: number = selected.exclusive
    ? Math.ceil(selected.value) - 1
    : Math.floor(selected.value);
  return {
    value:
      selected.exclusive && integer >= selected.value
        ? nextRepresentable(selected.value, false)
        : integer,
    exclusive: false,
  };
};

/**
 * Reads one bound, which may be infinite.
 *
 * A type tag built from an overflowing literal (`Maximum<1e400>`) carries an
 * infinite bound (#2452). `-Infinity` below or `Infinity` above excludes no
 * finite number, so it is no bound at all; `Infinity` below or `-Infinity`
 * above excludes every finite number, so no value can be generated.
 */
const boundary = (
  value: number | undefined,
  exclusive: boolean,
  side: "lower" | "upper",
): IBoundary | null => {
  if (value === undefined) return null;
  if (Number.isFinite(value)) return { value, exclusive };
  if (value === (side === "lower" ? -Infinity : Infinity)) return null;
  throw new Error("Numeric range has no finite value.");
};

const selectBoundary = (
  x: IBoundary | null,
  y: IBoundary | null,
  compare: (x: number, y: number) => number,
): IBoundary | null => {
  if (x === null) return y;
  if (y === null) return x;
  if (x.value === y.value)
    return { value: x.value, exclusive: x.exclusive || y.exclusive };
  return compare(x.value, y.value) === x.value ? x : y;
};

interface IBoundary {
  value: number;
  exclusive: boolean;
}

/**
 * Advances one IEEE 754 binary64 bit pattern, including signed zero and
 * subnormals.
 */
const nextRepresentable = (value: number, upward: boolean): number => {
  if (value === 0) return upward ? Number.MIN_VALUE : -Number.MIN_VALUE;
  const view: DataView = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, value);
  const bits: bigint = view.getBigUint64(0);
  view.setBigUint64(0, bits + (value > 0 === upward ? BigInt(1) : -BigInt(1)));
  return view.getFloat64(0);
};

typia/src/internal/_randomMultiple.ts:
import {
  _IDecimal,
  _IDecimalRatio,
  _decimalDecompose,
  _decimalDivide,
  _decimalGcd,
  _decimalIntegerStep,
  _decimalPower,
  _decimalToNumber,
} from "./_decimal";
import { _isMultipleOf } from "./_isMultipleOf";

/**
 * Generate a number that is a multiple of a decimal step inside a range.
 *
 * The quotient range is computed exactly, nearby candidates are tested for
 * being doubles that the multiple test accepts, and further candidates are
 * searched across exponent bands when none is found. It throws when the range
 * is empty or its bounded search finds no accepted candidate.
 *
 * The optional source supplies draws in [0, 1); it defaults to the platform
 * source resolved when this helper is called. Nested draws use the same
 * source.
 *
 * @evidence contracts/common.md#principled-implementation The step is read as a decimal and exact bigint ratios determine inclusive or exclusive quotient bounds. Selected, boundary and nearby quotients are converted to numbers and checked against the requested bounds and exact multiple predicate. Fallbacks search integer binary exponent bands and decimal exponents -324 through 308 with coefficients limited to fifteen digits. A returned candidate passes the predicate; failure of the bounded candidate search is not a proof that every possible decimal representation was examined.
 * @evidence contracts/common.md#clear-and-simple-design One public function and many private helpers for bounds, candidates and alignment, each used by the search; the search is long because doubles cannot represent every decimal multiple.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The final check uses the same predicate as the validator. Empty ranges and unsuccessful bounded searches throw; no candidate is accepted merely because it was sampled or rounded.
 * @evidence contracts/common.md#meaningful-documentation The doc states the exact quotient range, the candidate search and the failure case; the private helpers are covered by this function's answer.
 */
export const _randomMultiple = (
  props: {
    minimum: number;
    maximum: number;
    multipleOf: number;
    exclusiveMinimum: boolean;
    exclusiveMaximum: boolean;
    integer: boolean;
  },
  source: () => number = Math.random,
): number => {
  const step: _IDecimal | null = props.integer
    ? _decimalIntegerStep(props.multipleOf)
    : _decimalDecompose(props.multipleOf);
  if (step === null || step.coefficient <= BigInt(0))
    throw new Error("The multipleOf value must be a positive finite number.");

  const lower: _IDecimalRatio | null = _decimalDivide(props.minimum, step);
  const upper: _IDecimalRatio | null = _decimalDivide(props.maximum, step);
  if (lower === null || upper === null)
    throw new Error("The random number range must be finite.");
  const minimum: bigint = lowerBound(lower, props.exclusiveMinimum);
  const maximum: bigint = upperBound(upper, props.exclusiveMaximum);
  if (minimum > maximum)
    throw new Error("The range does not contain a multipleOf value.");

  const selected: bigint = randomBigint(minimum, maximum, source);
  const candidates: bigint[] = unique([
    selected,
    minimum,
    maximum,
    clamp(BigInt(0), minimum, maximum),
    clamp(BigInt(1), minimum, maximum),
    clamp(BigInt(-1), minimum, maximum),
    ...nearby(selected, minimum, maximum),
  ]);
  for (const coefficient of candidates) {
    const value: number = _decimalToNumber({
      coefficient: step.coefficient * coefficient,
      exponent: step.exponent,
    });
    if (isValid(props, value)) return value;
  }
  const aligned: number | null = findRepresentableIntegerMultiple(
    props,
    source,
  );
  if (aligned !== null) return aligned;
  const decimalAligned: number | null = findRepresentableDecimalMultiple(
    props,
    step,
    source,
  );
  if (decimalAligned !== null) return decimalAligned;
  throw new Error(
    "The range does not contain a representable multipleOf value.",
  );
};

const isValid = (
  props: Parameters<typeof _randomMultiple>[0],
  value: number,
): boolean =>
  Number.isFinite(value) &&
  (props.integer === false || Number.isInteger(value)) &&
  (props.exclusiveMinimum ? value > props.minimum : value >= props.minimum) &&
  (props.exclusiveMaximum ? value < props.maximum : value <= props.maximum) &&
  _isMultipleOf(value, props.multipleOf);

const findRepresentableDecimalMultiple = (
  props: Parameters<typeof _randomMultiple>[0],
  step: _IDecimal,
  source: () => number,
): number | null => {
  const limit: bigint = BigInt("999999999999999");
  for (let exponent = -324; exponent <= 308; ++exponent) {
    const unit: _IDecimal = { coefficient: BigInt(1), exponent };
    const lower: _IDecimalRatio | null = _decimalDivide(props.minimum, unit);
    const upper: _IDecimalRatio | null = _decimalDivide(props.maximum, unit);
    if (lower === null || upper === null) return null;

    const coefficientMinimum: bigint = max(
      -limit,
      lowerBound(lower, props.exclusiveMinimum),
    );
    const coefficientMaximum: bigint = min(
      limit,
      upperBound(upper, props.exclusiveMaximum),
    );
    if (coefficientMinimum > coefficientMaximum) continue;

    const coefficientStep: bigint = decimalCoefficientStep(step, exponent);
    const minimum: bigint = lowerBound(
      { numerator: coefficientMinimum, denominator: coefficientStep },
      false,
    );
    const maximum: bigint = upperBound(
      { numerator: coefficientMaximum, denominator: coefficientStep },
      false,
    );
    if (minimum > maximum) continue;

    const selected: bigint = randomBigint(minimum, maximum, source);
    for (const quotient of unique([
      selected,
      minimum,
      maximum,
      clamp(BigInt(0), minimum, maximum),
      ...nearby(selected, minimum, maximum),
    ])) {
      const value: number = _decimalToNumber({
        coefficient: coefficientStep * quotient,
        exponent,
      });
      if (isValid(props, value)) return value;
    }
  }
  return null;
};

const decimalCoefficientStep = (step: _IDecimal, exponent: number): bigint => {
  const difference: number = exponent - step.exponent;
  if (difference >= 0) {
    const power: bigint = _decimalPower(difference);
    return step.coefficient / _decimalGcd(step.coefficient, power);
  }
  return step.coefficient * _decimalPower(-difference);
};

const findRepresentableIntegerMultiple = (
  props: Parameters<typeof _randomMultiple>[0],
  source: () => number,
): number | null => {
  const step: _IDecimal | null = _decimalIntegerStep(props.multipleOf);
  if (step === null) return null;
  const unit: _IDecimal = { coefficient: BigInt(1), exponent: 0 };
  const lower: _IDecimalRatio | null = _decimalDivide(props.minimum, unit);
  const upper: _IDecimalRatio | null = _decimalDivide(props.maximum, unit);
  if (lower === null || upper === null) return null;

  const minimum: bigint = lowerBound(lower, props.exclusiveMinimum);
  const maximum: bigint = upperBound(upper, props.exclusiveMaximum);
  if (minimum > maximum) return null;
  if (minimum <= BigInt(0) && maximum >= BigInt(0)) return 0;

  const candidate: bigint | null =
    minimum > BigInt(0)
      ? findPositiveAligned(minimum, maximum, step.coefficient, source)
      : (() => {
          const magnitude: bigint | null = findPositiveAligned(
            -maximum,
            -minimum,
            step.coefficient,
            source,
          );
          return magnitude === null ? null : -magnitude;
        })();
  if (candidate === null) return null;
  const value: number = Number(candidate);
  return isValid(props, value) ? value : null;
};

const findPositiveAligned = (
  minimum: bigint,
  maximum: bigint,
  integerStep: bigint,
  source: () => number,
): bigint | null => {
  const first: number = bitLength(minimum) - 1;
  const last: number = bitLength(maximum) - 1;
  for (let exponent = first; exponent <= last; ++exponent) {
    const bandMinimum: bigint = max(minimum, BigInt(1) << BigInt(exponent));
    const bandMaximum: bigint = min(
      maximum,
      (BigInt(1) << BigInt(exponent + 1)) - BigInt(1),
    );
    const quantum: bigint =
      exponent <= 52 ? BigInt(1) : BigInt(1) << BigInt(exponent - 52);
    const alignedStep: bigint =
      (integerStep / _decimalGcd(integerStep, quantum)) * quantum;
    const lower: bigint = lowerBound(
      { numerator: bandMinimum, denominator: alignedStep },
      false,
    );
    const upper: bigint = upperBound(
      { numerator: bandMaximum, denominator: alignedStep },
      false,
    );
    if (lower <= upper) return randomBigint(lower, upper, source) * alignedStep;
  }
  return null;
};

const bitLength = (value: bigint): number => value.toString(2).length;

const min = (x: bigint, y: bigint): bigint => (x < y ? x : y);
const max = (x: bigint, y: bigint): bigint => (x > y ? x : y);

const lowerBound = (ratio: _IDecimalRatio, exclusive: boolean): bigint => {
  const quotient: bigint = ratio.numerator / ratio.denominator;
  const remainder: bigint = ratio.numerator % ratio.denominator;
  const ceiling: bigint =
    quotient + (remainder > BigInt(0) ? BigInt(1) : BigInt(0));
  return (
    ceiling + (exclusive && remainder === BigInt(0) ? BigInt(1) : BigInt(0))
  );
};

const upperBound = (ratio: _IDecimalRatio, exclusive: boolean): bigint => {
  const quotient: bigint = ratio.numerator / ratio.denominator;
  const remainder: bigint = ratio.numerator % ratio.denominator;
  const floor: bigint =
    quotient - (remainder < BigInt(0) ? BigInt(1) : BigInt(0));
  return floor - (exclusive && remainder === BigInt(0) ? BigInt(1) : BigInt(0));
};

const randomBigint = (
  minimum: bigint,
  maximum: bigint,
  source: () => number,
): bigint => {
  const scale: bigint = BigInt(1) << BigInt(53);
  const sample: bigint = BigInt(
    Math.min(
      Number(scale - BigInt(1)),
      Math.floor(Math.max(0, source()) * Number(scale)),
    ),
  );
  return minimum + ((maximum - minimum + BigInt(1)) * sample) / scale;
};

const clamp = (value: bigint, minimum: bigint, maximum: bigint): bigint =>
  value < minimum ? minimum : value > maximum ? maximum : value;

const nearby = (
  selected: bigint,
  minimum: bigint,
  maximum: bigint,
): bigint[] => {
  const output: bigint[] = [];
  for (let distance = BigInt(1); distance <= BigInt(32); ++distance) {
    if (selected - distance >= minimum) output.push(selected - distance);
    if (selected + distance <= maximum) output.push(selected + distance);
  }
  return output;
};

const unique = (values: bigint[]): bigint[] => [...new Set(values)];

