import { _randomInteger } from "./_randomInteger";
import { _randomString } from "./_randomString";
import { _stringLength } from "./_stringLength";

export const _RANDOM_LENGTH_ERROR =
  "unable to generate a random string satisfying both the format and the length constraints.";

/**
 * Length bounds forwarded to a string format or pattern generator.
 *
 * `typia.random<T>()` passes this object to the `_randomFormat*` and
 * `_randomPattern` helpers whenever the string leaf also carries a `MinLength`
 * or `MaxLength` tag, so a constrained format or pattern is generated at a
 * length its own validator accepts (issue #2189).
 *
 * @evidence contracts/common.md#principled-implementation Two optional numbers carry the minimum and maximum length of a string leaf to a format or pattern generator.
 * @evidence contracts/common.md#clear-and-simple-design Two fields.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
 * @evidence contracts/common.md#meaningful-documentation The comment says when the generated code passes it.
 */
export interface _ILengthProps {
  /** Inclusive minimum string length in code points, when constrained. */
  minLength?: number;

  /** Inclusive maximum string length in code points, when constrained. */
  maxLength?: number;
}

/**
 * Builds the variable segment of a fixed-shape format string so that the total
 * length `fixed + segment.length` lands inside the requested window.
 *
 * `fixed` is the number of characters the format always contributes around the
 * segment, `fallback` is the segment length used when the leaf is unconstrained
 * on that side, and `minimum` is the smallest segment the format still
 * validates with. Throws when the window cannot be satisfied by this format's
 * shape (e.g. `Format<"email"> & MaxLength<3>`).
 *
 * @evidence contracts/common.md#principled-implementation A variable segment is drawn so that a fixed overhead plus the segment fits the requested window, with a floor for the shortest valid segment, and a window the shape cannot meet throws.
 * @evidence contracts/common.md#clear-and-simple-design One function over the string generator.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Failure is explicit.
 * @evidence contracts/common.md#meaningful-documentation The doc defines fixed, fallback and minimum.
 */
export const _randomSegmentLength = (
  props: _ILengthProps | undefined,
  fixed: number,
  fallback: number,
  minimum: number,
): string => {
  let low: number =
    props?.minLength === undefined ? minimum : props.minLength - fixed;
  if (low < minimum) low = minimum;
  // With only a lower bound, spread the segment across `fallback` extra
  // characters so the generated length varies, mirroring `_randomString`.
  const high: number =
    props?.maxLength === undefined ? low + fallback : props.maxLength - fixed;
  if (high < low || high < minimum) throw new Error(_RANDOM_LENGTH_ERROR);
  return _randomString({ type: "string", minLength: low, maxLength: high });
};

/**
 * Intersects the requested length window with the lengths a format's grammar
 * can express, and draws one of them.
 *
 * `minimum` and `maximum` are the shortest and longest values the format admits
 * — omit `maximum` when the grammar is open above — and `spread` is how far
 * past the floor an unbounded request may reach, so an open side still varies
 * the way `_randomString` does. The caller draws from the returned window and
 * applies whatever step its grammar has (base64 lengths are multiples of four,
 * a fractional second needs at least one digit).
 *
 * Throws only when the window and the grammar do not overlap at all. That is
 * the distinction the retry driver below cannot make: it redraws one shape, so
 * it gives up on every length that shape never emits even when the format
 * itself accepts one (issue #2284).
 *
 * @evidence contracts/common.md#principled-implementation The requested bounds are intersected with the lengths the grammar admits, with a spread for an open side, and an empty intersection throws, which is the one case where no length can satisfy both.
 * @evidence contracts/common.md#clear-and-simple-design One function that returns a window and leaves the step to the caller.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The window is arithmetic and is not a retry.
 * @evidence contracts/common.md#meaningful-documentation The doc explains the window, the spread and the issue.
 */
export const _randomLengthWindow = (
  props: _ILengthProps | undefined,
  format: { minimum: number; maximum?: number; spread?: number },
): { low: number; high: number } => {
  const ceiling: number = format.maximum ?? Number.MAX_SAFE_INTEGER;
  const low: number = Math.max(
    props?.minLength ?? format.minimum,
    format.minimum,
  );
  const high: number = Math.min(
    props?.maxLength ?? low + (format.spread ?? 0),
    ceiling,
  );
  if (low > high) throw new Error(_RANDOM_LENGTH_ERROR);
  return { low, high };
};

/**
 * Draws a length inside a window produced by {@link _randomLengthWindow}.
 *
 * @evidence contracts/common.md#principled-implementation A length is drawn uniformly inside the window through the integer generator.
 * @evidence contracts/common.md#clear-and-simple-design One function.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It uses the shared generator.
 * @evidence contracts/common.md#meaningful-documentation The one-line doc states the use.
 */
export const _randomLengthPick = (window: {
  low: number;
  high: number;
}): number =>
  _randomInteger({
    type: "integer",
    minimum: window.low,
    maximum: window.high,
  });

/**
 * Wraps a fixed-length format generator (uuid, date) with the requested length
 * window.
 *
 * Use it only where the grammar admits exactly one length, so a window that
 * excludes it is genuinely unsatisfiable. A format that can express more than
 * one length must build its value at a length drawn from
 * {@link _randomLengthWindow} instead; redrawing one shape cannot reach a length
 * that shape never emits.
 *
 * @evidence contracts/common.md#principled-implementation A fixed-length format is generated and accepted only when its length in characters fits the window, up to 256 draws, and otherwise throws, which is correct for a grammar with exactly one length and wrong for formats with several, as the doc says.
 * @evidence contracts/common.md#clear-and-simple-design One function.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Characters, not code units, are counted to stay consistent with the length tags.
 * @evidence contracts/common.md#meaningful-documentation The doc states when to use it and when not to.
 */
export const _randomFormatLength = (
  props: _ILengthProps | undefined,
  generate: () => string,
): string => {
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return generate();
  for (let i: number = 0; i < 256; ++i) {
    const value: string = generate();
    // Characters, not UTF-16 code units: `minLength` and `maxLength` are the
    // bounds the generated validator compares in characters. `uuid` and `date`,
    // the only two shapes routed through here, are ASCII, so the two counts
    // agree for them today -- this keeps one measure so a later non-ASCII
    // format cannot reintroduce the divergence unnoticed.
    const length: number = _stringLength(value);
    if (
      (props.minLength === undefined || length >= props.minLength) &&
      (props.maxLength === undefined || length <= props.maxLength)
    )
      return value;
  }
  throw new Error(_RANDOM_LENGTH_ERROR);
};

typia/src/internal/_stringLength.ts:
/**
 * Counts the code points yielded by ECMAScript string iteration.
 *
 * A surrogate pair counts once and an unpaired surrogate counts once. This is
 * neither UTF-16 code-unit length nor grapheme-cluster length.
 *
 * @evidence contracts/common.md#principled-implementation For-of uses the language string iterator, so incrementing once per yielded element implements code-point-oriented schema length independently of the UTF-16 units counted by String.length.
 * @evidence contracts/common.md#clear-and-simple-design One counter and one traversal implement the length without a temporary character array or a second Unicode segmentation policy.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Language-defined iteration applies uniformly; no strings, encodings or consumers are patched or special-cased.
 * @evidence contracts/common.md#meaningful-documentation The doc states that it counts code points through string iteration, so a surrogate pair counts once and the result is neither the UTF-16 length nor a grapheme count.
 */
export const _stringLength = (value: string): number => {
  let count: number = 0;
  for (const _ch of value) ++count;
  return count;
};

typia/src/internal/_stringLengthGte.ts:
/**
 * Test whether a string has at least the given number of code points.
 *
 * Iteration stops as soon as the count is reached, so a long string is not
 * scanned to its end.
 *
 * @evidence contracts/common.md#principled-implementation The iterator is consumed only until the count reaches the requested minimum, which decides the lower bound without scanning the whole string; a minimum of zero is true at once.
 * @evidence contracts/common.md#clear-and-simple-design One loop with an early return.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The unit is code points.
 * @evidence contracts/common.md#meaningful-documentation The doc states the early return and the code point unit.
 */
export const _stringLengthGte = (value: string, length: number): boolean => {
  let count: number = 0;
  if (length <= count) return true;
  for (const _ch of value) if (length <= ++count) return true;
  return false;
};

typia/src/internal/_stringLengthLte.ts:
/**
 * Test whether a string has at most the given number of code points.
 *
 * Iteration stops as soon as the count is exceeded, so a long string is not
 * scanned to its end.
 *
 * @evidence contracts/common.md#principled-implementation The iterator is consumed until the count exceeds the maximum, which decides the upper bound without scanning past it; a negative maximum is false at once.
 * @evidence contracts/common.md#clear-and-simple-design One loop with an early return.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The unit is code points.
 * @evidence contracts/common.md#meaningful-documentation The doc states the early return and the code point unit.
 */
export const _stringLengthLte = (value: string, length: number): boolean => {
  let count: number = 0;
  if (!(count <= length)) return false;
  for (const _ch of value) if (!(++count <= length)) return false;
  return true;
};

import { TypeGuardError } from "../TypeGuardError";

/**
 * Throw a TypeGuardError built from the failure properties; this is the default
 * thrower of emitted assertions.
 *
 * @evidence contracts/common.md#principled-implementation The function throws a TypeGuardError built from the failure properties, which is the default thrower that emitted assertions call.
 * @evidence contracts/common.md#clear-and-simple-design One statement, a named function so emitted code has a stable import.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It adds no behavior beyond the constructor.
 * @evidence contracts/common.md#meaningful-documentation A comment states that it always throws.
 */
export const _throwTypeGuardError = (props: TypeGuardError.IProps) => {
  throw new TypeGuardError(props);
};

typia/src/internal/_validateReport.ts:
import { IValidation } from "@typia/interface";

/**
 * Create the reporter that validation functions use to collect errors.
 *
 * The returned function keeps an error only when it is exceptionable and its
 * path is neither an ancestor nor a descendant of the last kept path, so a
 * failing leaf is not also reported as every enclosing value. An undefined
 * value gets a default description when none was supplied. Kept errors retain
 * their original references, and filling that description updates the error. It
 * always returns false so emitted code can return it directly.
 *
 * @evidence contracts/common.md#principled-implementation The reporter pushes the original error onto the list only when it is exceptionable and its path is neither an ancestor nor a descendant of the last pushed one, so a failing leaf is not also reported as every enclosing value. For an undefined value it fills a missing description while preserving supplied text; it always returns false so emitted code can return it directly.
 * @evidence contracts/common.md#clear-and-simple-design One closure with two private predicates.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The suppression is path-based and general.
 * @evidence contracts/common.md#meaningful-documentation A comment states the suppression and the false result.
 */
export const _validateReport = (array: IValidation.IError[]) => {
  const isAncestor = (ancestor: string, descendant: string): boolean =>
    descendant === ancestor ||
    descendant.startsWith(`${ancestor}.`) ||
    descendant.startsWith(`${ancestor}[`);
  const reportable = (path: string): boolean => {
    if (array.length === 0) return true;
    const last: string = array[array.length - 1]!.path;
    return isAncestor(path, last) === false && isAncestor(last, path) === false;
  };
  return (exceptable: boolean, error: IValidation.IError): false => {
    if (exceptable && reportable(error.path)) {
      if (error.value === undefined)
        error.description ??= [
          "The value at this path is `undefined`.",
          "",
          `Please fill the \`${error.expected}\` typed value next time.`,
        ].join("\n");
      array.push(error);
    }
    return false;
  };
};

typia/src/internal/private/__notationRen:
/**
 * Shared outer walk for the `camel`/`pascal` notations.
 *
 * Mirrors the `CamelCase<T>` / `PascalCase<T>` typings: leading underscores are
 * preserved verbatim, an all-underscore key stays untouched, and the presence
 * of any remaining underscore — not the number of non-empty segments — selects
 * the `snake` conversion. Routing on underscore presence keeps a trailing or
 * doubled underscore (`fooBar_`) on the same path the type takes, instead of
 * collapsing it to the underscore-free `plain` path.
 *
 * @evidence contracts/common.md#principled-implementation Leading underscores are kept, an all-underscore key is returned as is and the presence of an underscore in the rest selects the snake conversion, which keeps a trailing or doubled underscore on the path the CamelCase and PascalCase typings take.
 * @evidence contracts/common.md#clear-and-simple-design One curried function parameterized by the two strategies that the camel and pascal notations supply.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The routing rule is the typings' own.
 * @evidence contracts/common.md#meaningful-documentation The doc states the routing rule and why it uses underscore presence.
 */
export const __notationRename =
  (props: { plain: (str: string) => string; snake: (str: string) => string }) =>
  (str: string): string => {
    let prefix: string = "";
    while (str.startsWith("_")) {
      prefix += "_";
      str = str.substring(1);
    }
    if (str.length === 0) return prefix;
    return `${prefix}${str.includes("_") ? props.snake(str) : props.plain(str)}`;
  };

typia/src/internal/private/__randomCompo:
import { _randomInteger } from "../_randomInteger";

/**
 * Splits `total` into `count` parts, each inside `[minimum, maximum]`.
 *
 * Used where a format's length is the sum of its segments — an IPv4 octet spans
 * one to three digits, an IPv6 group one to four — so a requested total length
 * is realized by choosing how many characters each segment contributes instead
 * of redrawing whole addresses and hoping one lands in the window (issue
 * #2284).
 *
 * The caller guarantees `count * minimum <= total <= count * maximum`; each
 * part is drawn from the range that still leaves the remaining parts
 * satisfiable. Counts, lengths and segment bounds are nonnegative integers.
 *
 * @evidence contracts/common.md#principled-implementation A total is split into parts within a range by drawing each part from the interval that still leaves the remaining parts satisfiable, so the caller's guarantee that the total is within `count * minimum` and `count * maximum` yields a valid composition without retrying.
 * @evidence contracts/common.md#clear-and-simple-design One function.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The method is constructive and not a redraw loop.
 * @evidence contracts/common.md#meaningful-documentation The doc states the guarantee and the use for formats.
 */
export const __randomComposition = (props: {
  total: number;
  count: number;
  minimum: number;
  maximum: number;
}): number[] => {
  const parts: number[] = [];
  let remaining: number = props.total;
  for (let i: number = 0; i < props.count; ++i) {
    const rest: number = props.count - i - 1;
    const value: number = _randomInteger({
      type: "integer",
      minimum: Math.max(props.minimum, remaining - rest * props.maximum),
      maximum: Math.min(props.maximum, remaining - rest * props.minimum),
    });
    parts.push(value);
    remaining -= value;
  }
  return parts;
};

/**
 * Draws `length` characters of the base64 alphabet.
 *
 * The caller passes a multiple of four, which `format: "byte"` accepts without
 * padding; every character below is in the alphabet its validator spells out,
 * so the result needs no encoding step.
 *
 * @evidence contracts/common.md#principled-implementation Each character is drawn from the 64-symbol alphabet, which is the alphabet the byte validator accepts, so a multiple-of-four length is valid without an encoder.
 * @evidence contracts/common.md#clear-and-simple-design One loop.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The alphabet is the format's.
 * @evidence contracts/common.md#meaningful-documentation The doc states the multiple-of-four precondition.
 */
export const __randomBase64 = (length: number): string => {
  let text: string = "";
  for (let i: number = 0; i < length; ++i)
    text +=
      BASE64[
        _randomInteger({
          type: "integer",
          minimum: 0,
          maximum: BASE64.length - 1,
        })
      ];
  return text;
};

const BASE64 =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/**
 * Draws `length` decimal digits, leading zeros included.
 *
 * @evidence contracts/common.md#principled-implementation Each character is a digit from zero to nine, leading zeros included.
 * @evidence contracts/common.md#clear-and-simple-design One loop.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It uses the shared integer generator.
 * @evidence contracts/common.md#meaningful-documentation A one-line doc states the digits.
 */
export const __randomDigits = (length: number): string => {
  let text: string = "";
  for (let i: number = 0; i < length; ++i)
    text += String(_randomInteger({ type: "integer", minimum: 0, maximum: 9 }));
  return text;
};

/**
 * Draws a positive integer count of decimal digits; a single digit may be zero.
 *
 * @evidence contracts/common.md#principled-implementation A number of the requested digit count without a leading zero, with one digit allowed to be zero, built from a nonzero first digit and random digits.
 * @evidence contracts/common.md#clear-and-simple-design One expression over the digit helper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It uses the shared integer generator.
 * @evidence contracts/common.md#meaningful-documentation A one-line doc states the digit count.
 */
export const __randomNumeric = (length: number): string =>
  length <= 1
    ? String(_randomInteger({ type: "integer", minimum: 0, maximum: 9 }))
    : String(_randomInteger({ type: "integer", minimum: 1, maximum: 9 })) +
      __randomDigits(length - 1);

typia/src/internal/private/__randomEpoch:
import { _randomInteger } from "../_randomInteger";

/**
 * Bounds of a random instant, in milliseconds since the epoch.
 *
 * @evidence contracts/common.md#principled-implementation Two optional millisecond numbers bound an instant, either of which may be open.
 * @evidence contracts/common.md#clear-and-simple-design Two fields.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
 * @evidence contracts/common.md#meaningful-documentation A comment states the unit and the meaning of each side.
 */
export interface __IEpochProps {
  /** Inclusive lower epoch-millisecond bound; defaults to zero. */
  minimum?: number;
  /** Inclusive upper bound; defaults to now or one year after a given minimum. */
  maximum?: number;
}

/**
 * Draws an epoch millisecond inside the requested bounds.
 *
 * Shared by the `date` and `date-time` generators, which had the same bound
 * expression written twice: `props?.maximum ?? props?.minimum === undefined`
 * parses as `props?.maximum ?? (props?.minimum === undefined)` because `??`
 * binds looser than `===`, so any supplied `maximum` made the condition truthy
 * and was replaced by `Date.now()`, while `maximum: 0` fell through to
 * `undefined + one year` and produced `NaN` (issue #2287). Keeping the
 * resolution in one place is what stops the two copies from drifting again.
 *
 * With no bound at all the window ends at the present instant; with only a
 * lower bound it spans one year from there.
 *
 * @evidence contracts/common.md#principled-implementation The upper bound defaults to now when there is no bound and to one year after the lower bound when only that is given, resolved in one place so the date and date-time generators cannot disagree, and an explicit maximum, including zero, is honored.
 * @evidence contracts/common.md#clear-and-simple-design One function.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The default window is stated and the precedence bug that once made the maximum ignored is the reason for sharing the code.
 * @evidence contracts/common.md#meaningful-documentation The doc states the defaults and the shared use.
 */
export const __randomEpoch = (props?: __IEpochProps): number => {
  const minimum: number = props?.minimum ?? 0;
  const maximum: number =
    props?.maximum ??
    (props?.minimum === undefined ? Date.now() : props.minimum + YEAR);
  return _randomInteger({
    type: "integer",
    minimum,
    maximum,
  });
};

const YEAR = 365 * 24 * 60 * 60 * 1_000;

typia/src/json.ts:
import {
  IJsonSchemaApplication,
  IJsonSchemaCollection,
  IJsonSchemaUnit,
  IValidation,
  Primitive,
} from "@typia/interface";

import { TypeGuardError } from "./TypeGuardError";
import { NoTransformConfigurationError } from "./transformers/NoTransformConfigurationError";

/* ===========================================================
    JSON
      - METADATA
      - PARSE
      - STRINGIFY
      - FACTORY FUNCTIONS
==============================================================
    METADATA
----------------------------------------------------------- */
/**
 * Generates JSON schema for type `T`.
 *
 * @danger You must configure the generic argument `Type`
 */
export function schema(): never;

/**
 * Generates JSON schema for type `T`.
 *
 * Creates {@link IJsonSchemaUnit} containing a main schema and shared
 * components. Named types are stored in `components` for `$ref` referencing.
 *
 * Specify OpenAPI version via `Version` generic (`"3.0"` or `"3.1"`). Default
 * is `"3.1"`. Key difference: `"3.1"` supports tuple types.
 *
 * @template Type Target type
 * @template Version OpenAPI version (`"3.0"` | `"3.1"`). Default `"3.1"`
 *
 * @returns JSON schema unit
 */
export function schema<
  Type extends unknown,
  Version extends "3.0" | "3.1" = "3.1",
>(): IJsonSchemaUnit<Version, Type>;

/** @internal */
export function schema(): never {
  NoTransformConfigurationError("json.schema");
}

/**
 * Generates JSON schemas for multiple types.
 *
 * @danger You must configure the generic argument `Types`
 */
export function schemas(): never;

/**
 * Generates JSON schemas for multiple types.
 *
 * Creates {@link IJsonSchemaCollection} containing schemas for all types in the
 * tuple. Named types are stored in `components` for `$ref` referencing.
 *
 * Specify OpenAPI version via `Version` generic (`"3.0"` or `"3.1"`). Default
 * is `"3.1"`. Key difference: `"3.1"` supports tuple types.
 *
 * @template Types Tuple of target types
 * @template Version OpenAPI version (`"3.0"` | `"3.1"`). Default `"3.1"`
 *
 * @returns JSON schema collection
 */
export function schemas<
  Types extends unknown[],
  Version extends "3.0" | "3.1" = "3.1",
>(): IJsonSchemaCollection<Version, Types>;

/** @internal */
export function schemas(): never {
  NoTransformConfigurationError("json.schemas");
}

/**
 * Generates JSON function schema application.
 *
 * @danger You must configure the generic argument `Class`
 */
export function application(): never;

/**
 * Generates JSON function schema application from class/interface.
 *
 * Creates {@link IJsonSchemaApplication} from a TypeScript class or interface,
 * generating JSON schemas for all methods, parameters, and return types.
 * Designed for building custom LLM function calling schemas.
 *
 * The returned object contains:
 *
 * - `functions`: Array of function metadata with parameter/return schemas
 * - `components`: Shared schema components for `$ref` referencing
 *
 * Use cases:
 *
 * - Custom LLM function calling schema formats
 * - API documentation or code generation tools
 * - Alternative LLM integrations that need full JSON Schema
 *
 * For standard LLM function calling, use {@link llm.application} instead, which
 * builds the LLM-optimized function schema directly.
 *
 * @template Class Target class or interface type
 * @template Version OpenAPI version (`"3.0"` | `"3.1"`). Default `"3.1"`
 *
 * @returns JSON function schema application
 */
export function application<
  Class extends object,
  Version extends "3.0" | "3.1" = "3.1",
>(): IJsonSchemaApplication<Version, Class>;

/** @internal */
export function application(): never {
  NoTransformConfigurationError("json.application");
}

/* -----------------------------------------------------------
    PARSE
----------------------------------------------------------- */
/**
 * Parses JSON string with assertion.
 *
 * @danger You must configure the generic argument `T`
 */
export function assertParse(
  input: string,
  errorFactory?: undefined | ((props: TypeGuardError.IProps) => Error),
): never;

/**
 * Parses JSON string with assertion.
 *
 * Combines `JSON.parse()` with {@link assert}. Throws {@link TypeGuardError} when
 * parsed value doesn't match type `T`.
 *
 * Related functions:
 *
 * - {@link isParse} — Returns `null` instead of throwing
 * - {@link validateParse} — Returns detailed validation errors
 *
 * @template T Target type for parsed value
 *
 * @param input JSON string to parse
 * @param errorFactory Custom error factory receiving
 *   {@link TypeGuardError.IProps}
 *
 * @returns Parsed value of type `T`
 *
 * @throws {TypeGuardError} When parsed value doesn't conform to type `T`
 */
export function assertParse<T>(
  input: string,
  errorFactory?: undefined | ((props: TypeGuardError.IProps) => Error),
): Primitive<T>;

/** @internal */
export function assertParse<T>(): Primitive<T> {
  NoTransformConfigurationError("json.assertParse");
}

/**
 * Parses JSON string with type checking.
 *
 * @danger You must configure the generic argument `T`
 */
export function isParse(input: string): never;

/**
 * Parses JSON string with type checking.
 *
 * Combines `JSON.parse()` with {@link is}. Returns `null` when parsed value
 * doesn't match type `T`.
 *
 * Related functions:
 *
 * - {@link assertParse} — Throws instead of returning `null`
 * - {@link validateParse} — Returns detailed validation errors
 *
 * @template T Target type for parsed value
 *
 * @param input JSON string to parse
 *
 * @returns Parsed value of type `T`, or `null` if invalid
 */
export function isParse<T>(input: string): Primitive<T> | null;

/** @internal */
export function isParse<T>(): Primitive<T> | null {
  NoTransformConfigurationError("json.isParse");
}

/**
 * Parses JSON string with validation.
 *
 * @danger You must configure the generic argument `T`
 */
export function validateParse(input: string): never;

/**
 * Parses JSON string with validation.
 *
 * Combines `JSON.parse()` with {@link validate}. Returns
 * {@link IValidation.IFailure} with all errors on mismatch, or
 * {@link IValidation.ISuccess} with parsed value.
 *
 * Related functions:
 *
 * - {@link assertParse} — Throws on first error
 * - {@link isParse} — Returns `null` instead of error details
 *
 * @template T Target type for parsed value
 *
 * @param input JSON string to parse
 *
 * @returns Validation result containing parsed value or errors
 */
export function validateParse<T>(input: string): IValidation<Primitive<T>>;

/** @internal */
export function validateParse<T>(): IValidation<Primitive<T>> {
  NoTransformConfigurationError("json.validateParse");
}

/* -----------------------------------------------------------
    STRINGIFY
----------------------------------------------------------- */
/**
