   * @evidence contracts/common.md#meaningful-documentation The one-line comment names the HTTP method of an operation.
   */
  export type Method =
    | "get"
    | "post"
    | "put"
    | "delete"
    | "options"
    | "head"
    | "patch"
    | "trace";

  /**
   * Transfer protocol supported by Swagger v2.
