import { TagBase } from "./TagBase";

/**
 * MIME type metadata for string content.
 *
 * `ContentMediaType<Type>` is a type tag that documents the media type of
 * string content. This is metadata-only - no runtime validation is performed.
 * The information appears in generated JSON Schema output.
 *
 * This is useful when a string property contains encoded binary data or
 * structured content that should be interpreted according to a specific media
 * type, such as base64-encoded images or embedded JSON.
 *
 * Common MIME types:
 *
 * - `"application/json"`: JSON data as string
 * - `"application/xml"`: XML data as string
 * - `"image/png"`: Base64-encoded PNG image
 * - `"image/jpeg"`: Base64-encoded JPEG image
 * - `"application/octet-stream"`: Generic binary data
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @example
 *   interface Document {
 *     // Base64-encoded PNG image
 *     thumbnail: string & ContentMediaType<"image/png">;
 *     // JSON stored as string
 *     metadata: string & ContentMediaType<"application/json">;
 *   }
 *
 * @template Value MIME type string literal
 *
 * @evidence contracts/common.md#principled-implementation The tag records the MIME string literal in `schema.contentMediaType` for string targets, matching the JSON Schema keyword of that name. `value` is undefined and there is no `validate`, so the type documents the encoding without claiming to check the content.
 * @evidence contracts/common.md#clear-and-simple-design One TagBase record, parameterized by the media type literal; no helpers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Metadata only; no runtime decoding or content sniffing is implied or faked.
 * @evidence contracts/common.md#meaningful-documentation The comment states that it is metadata-only, lists common MIME values and shows both an encoded-image and JSON-in-string example.
 */
export type ContentMediaType<Value extends string> = TagBase<{
  target: "string";
  kind: "contentMediaType";
  value: undefined;
  schema: {
    contentMediaType: Value;
  };
}>;

@typia/interface/src/tags/Default.ts:
import { TagBase } from "./TagBase";

/**
 * Default value metadata for JSON Schema generation.
 *
 * `Default<Value>` is a type tag that specifies a default value for a property
 * in the generated JSON Schema. This is metadata-only - typia does not
 * automatically apply default values at runtime.
 *
 * The default value appears in the `default` field of the JSON Schema output,
 * which API documentation tools and code generators can use to show default
 * values or generate code that applies them.
 *
 * Primitive literals and readonly tuples of primitive literals are supported.
 * Array defaults must be concrete tuples, normally captured with `as const`; an
 * open array type such as `string[]` does not identify a value to emit. For
 * object defaults, use optional properties with runtime default assignment.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @example
 *   interface Config {
 *     // Default to 10 items per page
 *     pageSize: (number & Default<10>) | undefined;
 *     // Default to enabled
 *     enabled: (boolean & Default<true>) | undefined;
 *     // Default sort order
 *     sortOrder: (string & Default<"asc">) | undefined;
 *     // Default selected columns
 *     columns: (string[] & Default<readonly ["id", "name"]>) | undefined;
 *   }
 *
 * @template Value The primitive or readonly tuple default value
 *
 * @evidence contracts/common.md#principled-implementation The target is derived from the literal (array for readonly tuples, otherwise boolean, bigint, number or string) and the literal is copied into `schema.default`; a bigint is rendered as the JSON number `Numeric<Value>` obtained by template-literal inference from its decimal text, and tuples are mapped element by element. A bigint outside the double-precision safe range is therefore represented by the nearest number the inference yields, which is a limitation of JSON numbers. The tag is exclusive, so only one default applies.
 * @evidence contracts/common.md#clear-and-simple-design Private Numeric, DefaultAtomic, DefaultArray and JsonDefault separate the permitted values from the JSON rendering; each is used once by the tag.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Typia does not apply the default at runtime, and the tag does not simulate that; open arrays are rejected by the constraint rather than guessed at.
 * @evidence contracts/common.md#meaningful-documentation The comment says the default is documentation metadata, which literals and tuples are accepted, why open arrays are not, and shows each form.
 */
export type Default<Value extends DefaultAtomic | DefaultArray> = TagBase<{
  target: Value extends DefaultArray
    ? "array"
    : Value extends boolean
      ? "boolean"
      : Value extends bigint
        ? "bigint"
        : Value extends number
          ? "number"
          : "string";
  kind: "default";
  value: Value;
  exclusive: true;
  schema: { default: JsonDefault<Value> };
}>;

type Numeric<T extends bigint> = `${T}` extends `${infer N extends number}`
  ? N
  : never;

type DefaultAtomic = boolean | bigint | number | string;
type DefaultArray = readonly [] | readonly [DefaultAtomic, ...DefaultAtomic[]];

type JsonDefault<Value> = Value extends bigint
  ? Numeric<Value>
  : Value extends DefaultArray
    ? { [Key in keyof Value]: JsonDefault<Value[Key]> }
    : Value;

