// type, even one with a private constructor), so an instance/plain-object method
// named `from` cannot seed a spurious arm. `from` counts as a constructing
// factory only when it RETURNS the instance type (looking through a `| null` /
// `| undefined` failure arm) — a `from` whose return is unrelated (a helper like
// `from(text): number`), untyped (`any`), or that constructs nothing (`never` /
// only `null`/`undefined`, where `NonNullable` collapses to `never`) does not
// hijack the strategy, and one returning a base/supertype (e.g. an inherited
// `from`) falls through to field copy, which safely captures the subclass's own
// fields.
type ClassifiableFactory<T> = [ClassInstanceType<T>] extends [never]
  ? never
  : T extends { from: (...args: infer A) => infer R }
    ? IsAny<R> extends true
      ? never
      : [NonNullable<R>] extends [never]
        ? never
        : [NonNullable<R>] extends [ClassInstanceType<T>]
          ? ClassifiableSeed<A>
          : never
    : never;

// `new T(x)` seed — single-argument callable. Two non-newable shapes must fall
// through to field copy, and they are excluded in two steps:
//  - a private/protected constructor does not match `abstract new` at all, so the
//    outer arm is already `never` for it;
//  - an ABSTRACT class DOES match `abstract new` (that is precisely its construct
//    signature) but TypeScript does not permit direct construction; abstract is
//    erased at runtime. The inner `T extends new (...) => any` gate drops it:
//    an abstract constructor type is not assignable to a concrete `new`
//    signature. Both then
//    field-copy, matching the transform (which never emits `new` for them).
type ClassifiableConstructor<T> = T extends abstract new (
  ...args: infer A
) => any
  ? T extends new (...args: any) => any
    ? ClassifiableSeed<A>
    : never
  : never;

// Field-copy property shape — the fallback strategy. Field copy is
// `Object.create(T.prototype)` + property assignment; it never calls the
// constructor, so it applies to ANY class and is NOT gated on `new T()` (a
// required-argument, or even private/protected, constructor does not disable
// field copy — the instance type is read from `prototype`). For a non-class type
// this is just the recursive property shape.
type ClassifiableProperties<T> = [ClassInstanceType<T>] extends [never]
  ? ClassifiableMain<T>
  : ClassifiableMain<ClassInstanceType<T>>;

// First parameter type, but only when the call is valid with a single argument:
// a first parameter must exist and every later parameter must be optional/rest
// (so `[]` is assignable to the rest). An `Iterable<U>` seed is rendered as
// `U[]` (the plain, JSON-decodable form typia can validate).
type ClassifiableSeed<A extends readonly any[]> = A extends readonly [
  infer P,
  ...infer Rest,
]
  ? [] extends Rest
    ? ClassifiableSeedValue<P>
    : never
  : A extends readonly []
    ? never
    : A extends readonly [(infer P)?, ...infer Rest]
      ? [] extends Rest
        ? ClassifiableSeedValue<P>
        : never
      : never;

// The seed of `from`/`new`, rendered as the plain, JSON-decodable form:
//  - `any`/`unknown` are rejected up front, else an `any`-typed seed (the common
//    `static from(json: any)` pattern) poisons the whole union to `any`.
//  - the bare-primitive arm is DISTRIBUTIVE and must stay ahead of `ValueOf`: a
//    union seed like `number | string | Date` keeps `string` as `string`.
//    Without it the non-distributive `ValueOf` arm fails for the whole union and
//    `string` falls to the `Iterable` arm, becoming `string[]`. `ValueOf` then
//    unwraps a boxed `String`/`Number` seed to its primitive.
//  - a tuple or array seed PRESERVES its shape (arity, element positions, and
//    the `readonly` modifier) by routing through the property path — exactly as
//    the spec promises for tuples, and matching how a tuple PROPERTY is handled.
//    Only a genuine collection that has no JSON form of its own — a `Set`/`Map`,
//    a typed array, or another bare iterable — renders as its element array. (A
//    naive `Iterable` arm would widen `[string, number]` to `(string | number)[]`
//    and accept `["a", "b"]`, which the emitted `C.from(data)` would then reject.)
//  - object seeds recurse through `ClassifiableMain`, so a nested class inside a
//    seed is classified too.
type ClassifiableSeedValue<P> =
  IsAny<P> extends true
    ? never
    : unknown extends P
      ? never
      : P extends string | number | bigint | boolean
        ? P
        : ValueOf<P> extends boolean | number | bigint | string
          ? ValueOf<P>
          : P extends readonly any[]
            ? ClassifiableMain<P>
            : P extends Iterable<infer U>
              ? ClassifiableMain<U>[]
              : P extends null | undefined
                ? never
                : ClassifiableMain<P>;

type ClassifiableMain<T> = T extends [never]
  ? never // (special trick for jsonable | null) type
  : ValueOf<T> extends boolean | number | bigint | string
    ? ValueOf<T>
    : T extends Function
      ? never
      : T extends object
        ? ClassifiableObject<T>
        : ValueOf<T>;

type ClassifiableObject<T extends object> = T extends readonly any[]
  ? ClassifiableArray<T>
  : T extends Set<infer U>
    ? Set<ClassifiableMain<U>> | ClassifiableMain<U>[]
    : T extends Map<infer K, infer V>
      ?
          | Map<ClassifiableMain<K>, ClassifiableMain<V>>
          | [ClassifiableMain<K>, ClassifiableMain<V>][]
      : T extends ReadonlyMap<infer K, infer V>
        ? // checked before ReadonlySet: a ReadonlyMap structurally matches
            // ReadonlySet<infer U> (methods are bivariant and ReadonlySet has no
            // distinguishing required member like the mutable `Set.add`), so the
            // more specific ReadonlyMap arm must run first — ReadonlySet has no
            // `get`, so it can never match this arm in turn.
            | ReadonlyMap<ClassifiableMain<K>, ClassifiableMain<V>>
            | [ClassifiableMain<K>, ClassifiableMain<V>][]
        : T extends ReadonlySet<infer U>
          ? ReadonlySet<ClassifiableMain<U>> | ClassifiableMain<U>[]
          : T extends WeakSet<any> | WeakMap<any, any>
            ? never
            : T extends NativeClass
              ? T
              : {
                  // Drop a key when its value carries no plain data. `NonNullable`
                  // looks through an optional `m?(): void` (type `(() => void) |
                  // undefined`), which would otherwise survive as `m?: undefined`
                  // and reject the class's own instance. A `WeakSet`/`WeakMap`
                  // member is also dropped (it cannot be rebuilt from plain data,
                  // and a `never` value would make the whole object
                  // unsatisfiable) — but a real `Set`/`Map` is structurally
                  // *wider* than its weak counterpart, so it must be matched and
                  // kept first, otherwise `Set extends WeakSet` would drop it.
                  // A purely-nullish field (`null`/`undefined`) is KEPT (its
                  // `NonNullable` is `never`, which would otherwise be vacuously a
                  // `Function` and dropped like a method) — `null` is valid plain
                  // data that the runtime field copy preserves.
                  [P in keyof T as [NonNullable<T[P]>] extends [never]
                    ? P
                    : NonNullable<T[P]> extends Function
                      ? never
                      : NonNullable<T[P]> extends Set<any> | Map<any, any>
                        ? P
                        : NonNullable<T[P]> extends
                              | WeakSet<any>
                              | WeakMap<any, any>
                          ? never
                          : P]: ClassifiableMain<T[P]>;
                };

// Array-likes are split into mutable vs `readonly` so the modifier survives;
// the object branch's key remapping (which drops methods) would otherwise
// mangle a `readonly` array into an index-signature object.
type ClassifiableArray<T extends readonly any[]> =
  T extends Array<infer U>
    ? IsTuple<T> extends true
      ? ClassifiableTuple<T>
      : ClassifiableMain<U>[]
    : T extends readonly (infer U)[]
      ? IsTuple<T> extends true
        ? Readonly<ClassifiableTuple<[...T]>>
        : readonly ClassifiableMain<U>[]
      : never;

type ClassifiableTuple<T extends readonly any[]> = T extends []
  ? []
  : T extends [infer F]
    ? [ClassifiableMain<F>]
    : T extends [infer F, ...infer Rest extends readonly any[]]
      ? [ClassifiableMain<F>, ...ClassifiableTuple<Rest>]
      : T extends [(infer F)?]
        ? [ClassifiableMain<F>?]
        : T extends [(infer F)?, ...infer Rest extends readonly any[]]
          ? [ClassifiableMain<F>?, ...ClassifiableTuple<Rest>]
          : [];

/**
 * The value `typia.plain.classify<T>` returns: a real instance.
 *
 * For a **class** type (`typeof C`) classify reconstructs and returns the
 * INSTANCE `C` (via `from`/`new`/field copy), so the result is
 * {@link ClassInstanceType}, not the constructor `typeof C`. For an instance
 * type or any non-class type, `ClassInstanceType` is `never`, so the result is
 * `T` unchanged — the common `classify<User>` call still returns `User`. The
 * conditional distributes over a union so a mixed `typeof A | number` maps
 * per-member to `A | number`.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @template T Target class (or instance) type to classify into
 *
 * @evidence contracts/common.md#principled-implementation For a class type the runtime returns an instance, so the result maps to `ClassInstanceType<T>`; for any other type the instance type is `never` and `T` passes through unchanged. Distribution over `T extends any` maps a mixed union per member.
 * @evidence contracts/common.md#clear-and-simple-design A three-branch conditional reusing ClassInstanceType keeps the result type and the input type derived from the same class test.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It is a pure type-level mapping with no cast or runtime effect, and it contains no consumer-specific branch.
 * @evidence contracts/common.md#meaningful-documentation The JSDoc states that classify returns the instance rather than the constructor, the unchanged non-class case and union distribution.
 */
export type ClassifyResult<T> = T extends any
  ? [ClassInstanceType<T>] extends [never]
    ? T
    : ClassInstanceType<T>
  : never;

@typia/interface/src/typings/ValidationP:
/**
 * Discriminated union for validation results.
 *
 * `ValidationPipe<T, E>` represents either a successful validation with data of
 * type `T`, or a failed validation with an array of errors of type `E`. Use the
 * `success` discriminant to narrow the type.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @template T Success data type
 * @template E Error type
 *
 * @evidence contracts/common.md#principled-implementation Literal true and false discriminants separate successful T data from E-array failure details, so TypeScript narrowing permits only the payload for the selected outcome.
 * @evidence contracts/common.md#clear-and-simple-design Two inline variants contain only their outcome and payload; shared generic parameters let validation consumers reuse the shape without coupling it to a particular error implementation.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The union represents both outcomes explicitly instead of asserting all results are successful or hiding failure information in an optional field.
 * @evidence contracts/common.md#meaningful-documentation The type comment explains success-based narrowing and both generic payload roles; each variant's members document its discriminant and available data or errors.
 */
export type ValidationPipe<T, E> =
  | {
      /** Selects the successful variant and makes data available. */
      success: true;

      /** Validated value for the successful outcome. */
      data: T;
    }
  | {
      /** Selects the failed variant and makes errors available. */
      success: false;

      /** Failure details using the validator's chosen error representation. */
      errors: E[];
    };

