          type: "number",
          name: "default",
          lines,
        }),
      }),
      description: describe(lines, [
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "default",
      ]),
    };
  };

