      ...compact({
        format: find({
          type: "string",
          name: "format",
          lines,
        }),
        pattern: find({
          type: "string",
          name: "pattern",
          lines,
        }),
        contentMediaType: find({
          type: "string",
          name: "contentMediaType",
          lines,
        }),
        minLength: find({
          type: "number",
          name: "minLength",
          lines,
        }),
        maxLength: find({
          type: "number",
          name: "maxLength",
          lines,
