              : 0,
    )) {
      while (taken.has(func.name)) func.name = `_${func.name}`;
      taken.add(func.name);
    }

    const version: string | undefined =
      props.migrate.document().info?.version || undefined;
    const app: IHttpLlmApplication = {
      config,
      functions,
      errors,
      ...(version !== undefined ? { version } : {}),
    };
    shorten(app, props.config?.maxLength ?? 64);
    return app;
  };

  /**
   * Converts a single {@link IHttpMigrateRoute} into an {@link IHttpLlmFunction}
   * by composing parameter/output schemas and validating function name
   * constraints.
   */
  const composeFunction = (props: {
    components: OpenApi.IComponents;
    route: IHttpMigrateRoute;
    config: IHttpLlmApplication.IConfig;
    errors: string[];
    index: number;
  }): IHttpLlmFunction | null => {
    // accessor prefix for error messages (mirrors OpenAPI document structure)
    const endpoint: string = `$input.paths[${JSON.stringify(props.route.path)}][${JSON.stringify(props.route.method)}]`;
    const operation: OpenApi.IOperation = props.route.operation();
    const description: string | undefined = concatDescription({
      summary: operation.summary,
      description: operation.description,
    });
    if ((description?.length ?? 0) > 1_024) {
      props.errors.push(
        `The description of the function is too long (must be equal or less than 1,024 characters, but ${description!.length.toLocaleString()} length).`,
      );
    }

    // build function name from route accessor, replacing forbidden chars
    const name: string = emend(props.route.accessor.join("_"));
    const isNameVariable: boolean = /^[a-zA-Z0-9_-]+$/.test(name);
    const isNameStartsWithNumber: boolean = /^[0-9]/.test(name[0] ?? "");
    if (isNameVariable === false)
      props.errors.push(
        `Elements of path (separated by '/') must be composed with alphabets, numbers, underscores, and hyphens`,
      );
    if (isNameStartsWithNumber === true)
      props.errors.push(`Function name cannot start with a number.`);

    //----
    // CONSTRUCT SCHEMAS
    //----
    // merge path parameters and grouped request inputs into one object schema
    const parameters: OpenApi.IJsonSchema.IObject = {
      type: "object",
      properties: Object.fromEntries([
        // path parameters (e.g., /users/:id)
        ...props.route.parameters.map(
          (s) =>
            [
              s.key,
              {
                ...s.schema,
                description: s.parameter().description ?? s.schema.description,
              },
            ] as const,
        ),
        // header parameters
        ...(props.route.headers
          ? [
              [
                props.route.headers.key,
                {
                  ...props.route.headers.schema,
                  title:
                    props.route.headers.title() ??
                    props.route.headers.schema.title,
                  description:
                    props.route.headers.description() ??
                    props.route.headers.schema.description,
                },
              ] as const,
            ]
          : []),
        // cookie parameters
        ...(props.route.cookies
          ? [
              [
                props.route.cookies.key,
                {
                  ...props.route.cookies.schema,
                  title:
                    props.route.cookies.title() ??
                    props.route.cookies.schema.title,
                  description:
                    props.route.cookies.description() ??
                    props.route.cookies.schema.description,
                },
              ] as const,
            ]
          : []),
        // query parameters
        ...(props.route.query
          ? [
              [
                props.route.query.key,
                {
                  ...props.route.query.schema,
                  title:
                    props.route.query.title() ?? props.route.query.schema.title,
                  description:
                    props.route.query.description() ??
                    props.route.query.schema.description,
                },
              ] as const,
            ]
          : []),
        // request body
        ...(props.route.body
          ? [
              [
                props.route.body.key,
                {
                  ...props.route.body.schema,
                  description:
                    props.route.body.description() ??
                    props.route.body.schema.description,
                },
              ] as const,
            ]
          : []),
      ]),
    };
    const required: string[] = [
      ...props.route.parameters.map((parameter) => parameter.key),
      ...(props.route.headers && props.route.headers.required !== false
        ? [props.route.headers.key]
        : []),
      ...(props.route.cookies && props.route.cookies.required !== false
        ? [props.route.cookies.key]
        : []),
      ...(props.route.query && props.route.query.required !== false
        ? [props.route.query.key]
        : []),
      ...(props.route.body && props.route.body.required !== false
        ? [props.route.body.key]
        : []),
    ];
    if (required.length !== 0) parameters.required = required;

    // convert merged object schema to LLM parameters
    const llmParameters: IResult<
      ILlmSchema.IParameters,
      IJsonSchemaTransformError
    > = LlmSchemaConverter.parameters({
      config: props.config,
      components: props.components,
      schema: parameters,
      accessor: `${endpoint}.parameters`,
    });

    // convert response schema to LLM output parameters
    const output:
      | IResult<ILlmSchema.IParameters, IJsonSchemaTransformError>
      | undefined = props.route.success
      ? LlmSchemaConverter.parameters({
          config: props.config,
          components: props.components,
          schema: props.route.success.schema as
            | OpenApi.IJsonSchema.IObject
            | OpenApi.IJsonSchema.IReference,
          accessor: `${endpoint}.responses[${JSON.stringify(props.route.success.status)}][${JSON.stringify(props.route.success.type)}].schema`,
        })
      : undefined;

    //----
    // CONVERSION
    //----
    // bail out if any validation or conversion failed
    if (
      output?.success === false ||
      llmParameters.success === false ||
      isNameVariable === false ||
      isNameStartsWithNumber === true ||
      (description?.length ?? 0) > 1_024
    ) {
      if (output?.success === false)
        props.errors.push(
          ...output.error.reasons.map((r) => `${r.accessor}: ${r.message}`),
        );
      if (llmParameters.success === false)
        props.errors.push(
          // rewrite internal accessor to match OpenAPI requestBody path
          ...llmParameters.error.reasons.map((r) => {
            const accessor: string = r.accessor.replace(
              `parameters.properties["body"]`,
              `requestBody.content[${JSON.stringify(props.route.body?.type ?? "application/json")}].schema`,
            );
            return `${accessor}: ${r.message}`;
          }),
        );
      return null;
    }

    const validate = OpenApiValidator.create({
      components: props.components,
      schema: parameters,
      required: true,
      equals: props.config.equals ?? false,
    });
    // The normal non-equals validator intentionally ignores additional
    // properties. For a flattened optional object, that would let the absent
    // union branch hide missing fields after any object-owned key is supplied.
    const conditionalGroups = [
      props.route.headers,
      props.route.cookies,
      props.route.query,
    ].flatMap((group) => {
      if (group === null || group === undefined) return [];
      const serializations = group.parameters ?? [];
      const object = serializations.find(
        (parameter) =>
          parameter.key === null &&
          parameter.parameter().required !== true &&
          (parameter.requiredProperties?.length ?? 0) !== 0,
      );
      if (object === undefined || serializations.length === 1) return [];
      const schema = resolveSchema(props.components)(group.schema);
      if (!("oneOf" in schema) || schema.oneOf[1] === undefined) return [];
      return [
        {
          key: group.key,
          object,
          serializations,
          validate: OpenApiValidator.create({
            components: props.components,
            schema: schema.oneOf[1],
            required: true,
            equals: props.config.equals ?? false,
          }),
        },
      ];
    });

    // assemble the LLM function
    return {
      method: props.route.method as "get",
      path: props.route.path,
      name,
      parameters: llmParameters.value,
      output: output?.value,
      description,
      deprecated: operation.deprecated,
      tags: operation.tags,
      parse: (input: string) => LlmJson.parse(input, llmParameters.value),
      coerce: (input: unknown) => LlmJson.coerce(input, llmParameters.value),
      validate: (input: unknown): IValidation<unknown> => {
        const result: IValidation<unknown> = validate(input);
        if (result.success === false || conditionalGroups.length === 0)
          return result;
        const record = result.data as Record<string, unknown>;
        for (const group of conditionalGroups) {
          const value = record[group.key];
          if (
            typeof value !== "object" ||
            value === null ||
            Array.isArray(value)
          )
            continue;
          if (
            isObjectParameterProvided({
              input: value as Record<string, unknown>,
              object: group.object,
              serializations: group.serializations,
            }) === false
          )
            continue;
          const exact: IValidation<unknown> = group.validate(value);
          if (exact.success === false)
            return {
              ...exact,
              data: result.data,
              errors: exact.errors.map((error) => ({
                ...error,
                path: error.path.replace("$input", `$input.${group.key}`),
              })),
            };
        }
        return result;
      },
      route: () => props.route as any,
      operation: () => props.route.operation(),
    };
  };

  const resolveSchema =
    (components: OpenApi.IComponents) =>
    (input: OpenApi.IJsonSchema): OpenApi.IJsonSchema => {
      let schema: OpenApi.IJsonSchema = input;
      const visited: Set<string> = new Set();
      while ("$ref" in schema) {
        const entry = OpenApiReferenceKey.find(
          components.schemas,
          schema.$ref,
          SCHEMAS,
        );
        if (entry === undefined || visited.has(entry.key)) break;
        visited.add(entry.key);
        schema = entry.value;
      }
      return schema;
    };

  const isObjectParameterProvided = (props: {
    input: Record<string, unknown>;
    object: IHttpMigrateRoute.ISerialization;
    serializations: IHttpMigrateRoute.ISerialization[];
  }): boolean => {
    const properties = new Set(props.object.properties ?? []);
    const occupied = new Set(
      props.serializations
        .filter((parameter) => parameter !== props.object)
        .flatMap((parameter) =>
          parameter.key !== null
            ? [parameter.key]
            : (parameter.properties ?? []),
        ),
    );
    return Object.entries(props.input).some(
      ([key, value]) =>
        value !== undefined &&
        (properties.has(key) ||
          (props.object.additionalProperties === true && !occupied.has(key))),
    );
  };

  /**
   * Shortens function names exceeding the character limit.
   *
   * Tries the non-empty accessor suffixes of at most `limit - 8` characters,
   * the room an index prefix needs, from the longest down: each as is, or with
   * an index prefix when that is taken. When none is free, it keeps as much of
   * the last accessor segment as fits beside a hash of the full name. Every
   * result is deterministic, fits the limit, and starts with no digit;
   * shortening throws when every such hashed name is taken, as all are below
   * 2.
   *
   * @evidence contracts/common.md#principled-implementation A name longer than the limit tries its non-empty accessor suffixes from the longest that leaves room for a counter prefix, each as is or with a counter, and otherwise takes a part of its last segment beside a hash, all deterministic and within the limit; it throws if every hashed candidate is taken.
   * @evidence contracts/common.md#clear-and-simple-design The suffix search is in this function, and the hash fallback and legal-name helper are separate private functions.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The abbreviation uses a deterministic hash and not a random identifier, as the abbreviate comment records.
   * @evidence contracts/common.md#meaningful-documentation The doc and the abbreviate doc give the rule, the constants and the issue behind the hash.
   */
  export const shorten = (
    app: IHttpLlmApplication,
    limit: number = 64,
  ): void => {
    // collect all names for uniqueness checks
    const dictionary: Set<string> = new Set();
    const longFunctions: IHttpLlmFunction[] = [];
    for (const func of app.functions) {
      dictionary.add(func.name);
      if (func.name.length > limit) {
        longFunctions.push(func);
      }
    }
    if (longFunctions.length === 0) return;

    let index: number = 0;
    for (const func of longFunctions) {
      let success: boolean = false;
      const rename = (str: string) => {
        dictionary.delete(func.name);
        dictionary.add(str);
        func.name = str;
        success = true;
      };
      // try dropping leading accessor segments to shorten the name
      // (e.g., "api_users_getById" → "users_getById" → "getById")
      for (let i: number = 1; i < func.route().accessor.length; ++i) {
        const shortName: string = legal(
          emend(func.route().accessor.slice(i).join("_")),
        );
        if (shortName.length === 0 || shortName.length > limit - 8)
          continue; // empty, or no room for the "_N_" prefix
        else if (dictionary.has(shortName) === false) rename(shortName);
        else {
          // name collision — prefix with a counter to disambiguate
          const newName: string = `_${index}_${shortName}`;
          if (dictionary.has(newName) === true) continue;
          rename(newName);
          ++index;
        }
        break;
      }
      // last resort — all suffix attempts failed or collided
      if (success === false) rename(abbreviate(func, limit, dictionary));
    }
  };
}

/**
 * Abbreviates a function name that no accessor suffix could shorten.
 *
 * Keeps as much of the last accessor segment, the most specific one, as fits
 * beside a hash of the full name, none of it below a limit of 9, and tries up
 * to a thousand hashes until the name is free. This used to be a random UUID:
 * the name changed on every composition, started with a digit ten times in
 * sixteen, which the composer forbids for any other name, and was longer than a
 * `limit` below 36 (#2456).
 */
const abbreviate = (
  func: IHttpLlmFunction,
  limit: number,
  taken: Set<string>,
): string => {
  const accessor: string[] = func.route().accessor;
  const head: string = legal(emend(accessor[accessor.length - 1] ?? ""));
  for (let salt: number = 0; salt < 1_000 && limit >= 2; ++salt) {
    const hash: string = hashName(
      salt === 0 ? func.name : `${func.name}#${salt}`,
    );
    // The leading base-36 digit of a 32-bit hash is only ever 0 or 1, so a
    // short name keeps the hash's tail.
    const room: number = limit - hash.length - 1;
    const name: string =
      room > 0
        ? `${head.slice(0, room)}_${hash}`
        : `_${hash.slice(-Math.floor(limit - 1))}`;
    if (taken.has(name) === false) return name;
  }
  throw new Error(
    `Error on HttpLlm.application(): maxLength ${limit} cannot hold a unique name for ${JSON.stringify(func.name)}.`,
  );
};

/**
 * Prefixes `_` to a name that starts with a digit.
 *
 * A custom `x-samchon-accessor` segment may start with one, and the composer
 * refuses such a function name everywhere else.
 */
const legal = (name: string): string =>
  /^[0-9]/.test(name) ? `_${name}` : name;

/** FNV-1a 32-bit hash of a name, in seven base-36 digits. */
const hashName = (text: string): string => {
  let hash: number = 0x811c9dc5;
  for (let i: number = 0; i < text.length; ++i) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(36).padStart(7, "0");
};

/** Replaces forbidden characters (`$`, `%`, `.`) with underscores. */
const emend = (str: string): string => {
  for (const ch of FORBIDDEN) str = str.split(ch).join("_");
  return str;
};

const FORBIDDEN = ["$", "%", "."];

/**
 * Concatenates summary and description into a single string.
 *
 * If both are present, joins them with a period and double newline, avoiding
 * duplication when the description already starts with the summary.
 */
const concatDescription = (p: {
  summary?: string | undefined;
  description?: string | undefined;
}): string | undefined => {
  if (!p.summary?.length || !p.description?.length)
    return p.summary || p.description;
  const summary: string = p.summary.endsWith(".")
    ? p.summary.slice(0, -1)
    : p.summary;
  return p.description.startsWith(summary)
    ? p.description
    : summary + ".\n\n" + p.description;
};

