import {
  IHttpMigrateApplication,
  IHttpMigrateRoute,
  OpenApi,
} from "@typia/interface";

import { EndpointUtil } from "../../utils/internal/EndpointUtil";
import { HttpMigrateRouteAccessor } from "./HttpMigrateRouteAccessor";
import { HttpMigrateRouteComposer } from "./HttpMigrateRouteComposer";

/**
 * Composes {@link IHttpMigrateApplication} from an emended OpenAPI document.
 *
 * Supported path and webhook operations become routes or failure records, and
 * the accessors of the successful routes are assigned together once all routes
 * are known.
 *
 * @evidence contracts/common.md#principled-implementation Operations from paths and webhooks are listed together without merging by key, composed in path and method order and reported in document order, then the accessors are assigned over all successful routes; this ordering keeps schema and accessor name ownership independent of how the document was sorted.
 * @evidence contracts/common.md#clear-and-simple-design A single exported compose function with a method table and entry comparator; accessor naming is delegated to HttpMigrateRouteAccessor.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Ordering follows a stated rule with issue references and not an arrangement chosen to match a test document.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment and function doc state the contract, and inline comments explain the webhook handling and the ordering.
 */
export namespace HttpMigrateApplicationComposer {
  /**
   * Migrate the supported operations of the document.
   *
   * The method set is HEAD, GET, POST, PUT, PATCH, DELETE and QUERY. OPTIONS,
   * TRACE and additional operations are not selected.
   *
   * Routes are composed in path and method order so that name collisions are
   * settled independently of the order of `paths`, and are reported in document
   * order. The document is modified: route composition sanitizes schemas and
   * emplaces component schemas, and a failed route leaves no component behind.
   *
   * @param document Emended OpenAPI document
   *
   * @returns Routes, per-operation errors and an accessor to the document
   *
   * @evidence contracts/common.md#principled-implementation Entries are flattened from paths and webhooks, composed in sorted order into route or message-list results and then split into routes and errors; the sort is stable so a path operation precedes a webhook with the same key and method. It modifies the supplied document through the route composer.
   * @evidence contracts/common.md#clear-and-simple-design One function with a private entry type, a method order table and a comparator.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The method order table is the supported method set, not a special case.
   * @evidence contracts/common.md#meaningful-documentation The doc states the ordering, the document modification and the result shape.
   */
  export const compose = (
    document: OpenApi.IDocument,
  ): IHttpMigrateApplication => {
    // Webhooks are migrated next to paths, not merged into them by key: a
    // webhook named like a path used to replace that whole path item, so its
    // operations vanished without a route or an error (#2455).
    const entries: IEntry[] = [document.paths, document.webhooks].flatMap(
      (collections) =>
        Object.entries(collections ?? {}).flatMap(([path, collection]) =>
          METHODS.filter((method) => collection[method] !== undefined).map(
            (method) => ({ path, method, operation: collection[method]! }),
          ),
        ),
    );

    // Compose in path and method order, not document order: a route that
    // emplaces a schema under a name another route also derives takes the
    // name by this order (#2451), so which route owns it must not change when
    // a tool re-sorts `paths`. The sort is stable, so a path operation still
    // precedes a webhook sharing its key and method. The routes are reported
    // in document order.
    const migrated: Array<IHttpMigrateRoute | string[]> = new Array(
      entries.length,
    );
    for (const index of entries
      .map((_, i) => i)
      .sort((x, y) => compareEntry(entries[x]!, entries[y]!)))
      migrated[index] = HttpMigrateRouteComposer.compose({
        document,
        method: entries[index]!.method,
        path: entries[index]!.path,
        emendedPath: EndpointUtil.reJoinWithDecimalParameters(
          entries[index]!.path,
        ),
        operation: entries[index]!.operation,
      });

    const errors: IHttpMigrateApplication.IError[] = [];
    const operations: IHttpMigrateRoute[] = [];
    entries.forEach((entry, i) => {
      const route: IHttpMigrateRoute | string[] = migrated[i]!;
      if (Array.isArray(route))
        errors.push({
          method: entry.method,
          path: entry.path,
          operation: () => entry.operation,
          messages: route,
        });
      else operations.push(route);
    });
    HttpMigrateRouteAccessor.overwrite(operations);
    return {
      document: () => document,
      routes: operations,
      errors,
    } satisfies IHttpMigrateApplication as IHttpMigrateApplication;
  };

  const METHODS = [
    "head",
    "get",
    "post",
    "put",
    "patch",
    "delete",
    "query",
  ] as const;

  interface IEntry {
    path: string;
    method: (typeof METHODS)[number];
    operation: OpenApi.IOperation;
  }

  const compareEntry = (x: IEntry, y: IEntry): number =>
    x.path < y.path
      ? -1
      : x.path > y.path
        ? 1
        : METHODS.indexOf(x.method) - METHODS.indexOf(y.method);
}

import { IHttpMigrateRoute } from "@typia/interface";

import { MapUtil } from "../../utils/MapUtil";
import { NamingConvention } from "../../utils/NamingConvention";
import { EndpointUtil } from "../../utils/internal/EndpointUtil";

/**
 * Assigns the accessor, parameter keys and argument names of migrated routes.
 *
 * Names are derived from the static path segments and settled in path order, so
 * a route keeps the plain name when another route derives the same one.
 *
 * @evidence contracts/common.md#principled-implementation Static path segments become a namespace and each route a method-like alias, with aliases escaped against siblings in path order so the first route keeps the plain alias, parameter keys escaped against each other and the reserved `connection` argument, and any accessor that is a prefix of another escaped, which keeps every route callable.
 * @evidence contracts/common.md#clear-and-simple-design One exported overwrite function with private collection and naming helpers; MapUtil.take lazily creates namespace entries, and that helper stays as ordinary shared code because its own declaration is not a selectable host.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The rules are structural and carry no route names; `x-samchon-accessor` is honored only when it is unambiguous.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment and the function doc state the alias settling, the key escaping and the prefix rule.
 */
export namespace HttpMigrateRouteAccessor {
  /**
   * Overwrite the placeholder accessor and the parameter keys of every route.
   *
   * Routes are grouped by namespace, an alias is escaped against its siblings,
   * and an `x-samchon-accessor` is honored only when exactly one route declares
   * it. A route whose accessor would also be a namespace of another route gets
   * an underscore prefix on the clashing segment. The routes are modified in
   * place.
   *
   * @param routes Routes whose accessors are still the lazy placeholder
   *
   * @evidence contracts/common.md#principled-implementation It groups routes by namespace, settles aliases in path order, escapes parameter keys against one another and `connection`, applies an unambiguous custom accessor and then prefixes accessors that would be both a namespace and a function. The final prefix check is repeated per route and scans all routes, which is quadratic in the number of routes.
   * @evidence contracts/common.md#clear-and-simple-design One function using small private helpers for grouping, names and predefined accessors.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Collision handling is by escaping and not by dropping routes.
   * @evidence contracts/common.md#meaningful-documentation The doc states the order dependency, the custom accessor rule and the in-place change.
   */
  export const overwrite = (routes: IHttpMigrateRoute[]): void => {
    const predefined: Map<string, number> = getPredefinedAccessors(routes);
    const dict: Map<string, IElement> = collect((op) =>
      op.path
        .split("/")
        .map((str) => ({
          original: str,
          static: str.replace(/\{[^{}]+\}/g, ""),
        }))
        .filter(
          (str) =>
            str.static.length !== 0 &&
            (str.original === str.static || /[a-zA-Z0-9_$]/.test(str.static)),
        )
        .map((str) => str.static)
        .map(EndpointUtil.normalize)
        .map((str) => (NamingConvention.variable(str) ? str : `_${str}`)),
    )(routes) as Map<string, IElement>;

    for (const props of dict.values()) {
      // Settle one namespace's aliases in path order, the order component
      // names are settled in (#2451): the first keeps its plain alias, and
      // each later duplicate is escaped against those settled before it. The
      // sort is stable, so a path operation precedes a webhook sharing its key.
      // Escaping every entry against every other left the plain alias to the
      // last in document order, so a webhook added after a path took the path
      // operation's accessor and function name (#2455).
      const settled: string[] = [];
      for (const entry of [...props.entries].sort((x, y) =>
        x.route.path < y.route.path ? -1 : x.route.path > y.route.path ? 1 : 0,
      )) {
        entry.alias = EndpointUtil.escapeDuplicate(
          [...props.children, ...settled].map(EndpointUtil.normalize),
        )(EndpointUtil.normalize(entry.alias));
        settled.push(entry.alias);

        const parameters: { name: string; key: string }[] = [
          ...entry.route.parameters,
          ...(entry.route.body ? [entry.route.body] : []),
          ...(entry.route.headers ? [entry.route.headers] : []),
          ...(entry.route.cookies ? [entry.route.cookies] : []),
          ...(entry.route.query ? [entry.route.query] : []),
        ];
        parameters.forEach(
          (p, i) =>
            (p.key = EndpointUtil.escapeDuplicate([
              "connection",
              entry.alias,
              ...parameters.filter((_, j) => i !== j).map((y) => y.key),
            ])(p.key)),
        );

        const accessor: string[] | undefined =
          entry.route.operation()["x-samchon-accessor"];
        if (accessor !== undefined && predefined.get(accessor.join(".")) === 1)
          entry.route.accessor = accessor;
        else entry.route.accessor = [...props.namespace, entry.alias];
      }
    }

    for (const x of routes) {
      while (true) {
        const neighbor: IHttpMigrateRoute | undefined = routes.find(
          (y) =>
            y.accessor.length < x.accessor.length &&
            x.accessor
              .slice(0, y.accessor.length)
              .every((v, i) => v === y.accessor[i]),
        );
        if (neighbor === undefined) break;
        x.accessor[neighbor.accessor.length - 1] =
          `_${x.accessor[neighbor.accessor.length - 1]}`;
      }
    }
  };

  const collect =
    (getter: (r: IHttpMigrateRoute) => string[]) =>
    (routes: IHttpMigrateRoute[]): Map<string, IElement> => {
      const dict: Map<string, IElement> = new Map();
      for (const r of routes) {
        const namespace: string[] = getter(r);
        let last: IElement = MapUtil.take(dict, namespace.join("."), () => ({
          namespace,
          children: new Set(),
          entries: [],
        }));
        last.entries.push({
          route: r,
          alias: getName(r),
        });
        namespace.slice(0, -1).forEach((_i, i, array) => {
          const partial: string[] = namespace.slice(0, array.length - i);
          const element: IElement = MapUtil.take(
            dict,
            partial.join("."),
            () => ({
              namespace: partial,
              children: new Set(),
              entries: [],
            }),
          );
          element.children.add(last.namespace.at(-1)!);
        });
        const top: IElement = MapUtil.take(dict, "", () => ({
          namespace: [],
          children: new Set(),
          entries: [],
        }));
        if (namespace.length) top.children.add(namespace[0]!);
      }
      return dict;
    };

  const getName = (op: IHttpMigrateRoute): string => {
    const method = op.method === "delete" ? "erase" : op.method;
    if (op.parameters.length === 0) return method;
    return (
      method +
      "By" +
      op.parameters.map((p) => EndpointUtil.capitalize(p.key)).join("And")
    );
  };

  const getPredefinedAccessors = (
    routes: IHttpMigrateRoute[],
  ): Map<string, number> => {
    const dict: Map<string, number> = new Map();
    for (const r of routes) {
      const accessor = r.operation()["x-samchon-accessor"]?.join(".");
      if (accessor === undefined) continue;
      else if (dict.has(accessor)) dict.set(accessor, dict.get(accessor)! + 1);
      else dict.set(accessor, 1);
    }
    return dict;
  };

  interface IElement {
    namespace: string[];
    entries: IEntry[];
    children: Set<string>;
  }
  interface IEntry {
    route: IHttpMigrateRoute;
    alias: string;
  }
}

import { IHttpMigrateRoute, OpenApi } from "@typia/interface";

import { NamingConvention } from "../../utils/NamingConvention";
import { EndpointUtil } from "../../utils/internal/EndpointUtil";
import { JsonCanonical } from "../../utils/internal/JsonCanonical";
import { ObjectDictionary } from "../../utils/internal/ObjectDictionary";
import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiSchemaSanitizer } from "../../utils/internal/OpenApiSchemaSanitizer";
import { OpenApiTypeChecker } from "../../validators/OpenApiTypeChecker";

/**
 * Composes one {@link IHttpMigrateRoute} from an OpenAPI operation.
 *
 * The operation's parameters are grouped into path, header, cookie and query
 * records, its bodies are classified by media type, and anonymous schemas are
 * emplaced as named components so the route can refer to them.
 *
 * @evidence contracts/common.md#principled-implementation A route is built by sanitizing the operation's schemas, classifying request and response bodies by media type, grouping header, cookie and query parameters into single objects with per-parameter serialization records, completing and checking path parameters, and emplacing anonymous schemas as named components whose names are escaped on collision. Failures are collected and returned together so one report names every problem.
 * @evidence contracts/common.md#clear-and-simple-design The exported compose wraps one large composeRoute and private helpers for bodies, schema sanitation, reference emplacement and comment writing; each handles one concern and is used by that function.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Style and media-type support follow the OpenAPI rules enumerated in the code, unsupported ones are rejected with a message, and nothing is accepted by naming a particular route or fixture.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment states the purpose; emplaceReference carries a long rationale with issue references and failure messages state the exact limitation.
 */
export namespace HttpMigrateRouteComposer {
  const SCHEMAS = "#/components/schemas/";

  /**
   * Properties of {@link compose}.
   *
   * @evidence contracts/common.md#principled-implementation The record carries the document, the method, original and emended paths and the operation, which is the minimum needed to name schemas and compose the route.
   * @evidence contracts/common.md#clear-and-simple-design Five fields that are all used by compose.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
   * @evidence contracts/common.md#meaningful-documentation A comment names it as the properties of compose.
   */
  export interface IProps {
    /** Live document receiving composed component schemas. */
    document: OpenApi.IDocument;

    /** HTTP method of the operation. */
    method: "head" | "get" | "post" | "put" | "patch" | "delete" | "query";

    /** Original OpenAPI path template. */
    path: string;

    /** Router path with colon parameters. */
    emendedPath: string;

    /** Live operation whose parameters and schemas are normalized. */
    operation: OpenApi.IOperation;
  }
  /**
   * Compose a route, or report why the operation cannot be migrated.
   *
   * The document and operation are modified: schemas are sanitized in place,
   * missing path parameters are added to the operation, and inline schemas
   * become components. When composition fails, the components added by this
   * call are removed so that a failed route owns no name.
   *
   * @param props Document, operation and path information
   *
   * @returns The route, or the list of failure messages
   *
   * @evidence contracts/common.md#principled-implementation The route is composed against the live document and, when it fails, the component schemas that this call added are deleted so a failed route owns no name; the document and operation are modified during composition, which callers must accept.
   * @evidence contracts/common.md#clear-and-simple-design A small wrapper that snapshots component names around composeRoute.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Rollback restores only names this call created, so no existing component is removed.
   * @evidence contracts/common.md#meaningful-documentation The doc comment states the mutation and the rollback.
   */
  export const compose = (props: IProps): IHttpMigrateRoute | string[] => {
    const before: Set<string> = new Set(
      Object.keys(props.document.components.schemas ?? {}),
    );
    const result: IHttpMigrateRoute | string[] = composeRoute(props);
    // A failed route is not migrated, so it keeps no component either, least
    // of all a name a valid route would otherwise own (#2451).
    if (Array.isArray(result) && props.document.components.schemas)
      for (const key of Object.keys(props.document.components.schemas))
        if (before.has(key) === false)
          delete props.document.components.schemas[key];
    return result;
  };

  const composeRoute = (props: IProps): IHttpMigrateRoute | string[] => {
    sanitizeOperationSchemas(props.document)(props.operation);

    //----
    // REQUEST AND RESPONSE BODY
    //----
    const body: false | null | IHttpMigrateRoute.IBody = emplaceBodySchema(
      props.document,
    )("request")((schema) =>
      emplaceReference({
        document: props.document,
        name:
          EndpointUtil.pascal(`I/Api/${props.path}`) +
          "." +
          EndpointUtil.pascal(`${props.method}/Body`),
        schema,
      }),
    )(props.operation.requestBody);
    const successResponse = selectSuccessResponse(props.operation.responses);
    const success: false | null | IHttpMigrateRoute.ISuccess = (() => {
      const body = emplaceBodySchema(props.document)("response")((schema) =>
        emplaceReference({
          document: props.document,
          name:
            EndpointUtil.pascal(`I/Api/${props.path}`) +
            "." +
            EndpointUtil.pascal(`${props.method}/Response`),
          schema,
        }),
      )(successResponse?.[1]);
      return body
        ? {
            ...body,
            status: successResponse![0],
          }
        : body;
    })();

    const failures: string[] = [];
    if (body === false)
      failures.push(
        `supports only JSON, "application/x-www-form-urlencoded", "multipart/form-data" and "text/plain" content types in the request body.`,
      );
    if (success === false)
      failures.push(
        `supports only JSON, "application/x-www-form-urlencoded" and "text/plain" content types in the response body.`,
      );

    //----
    // HEADERS AND QUERY
    //---
    const [headers, query, cookies] = (
      ["header", "query", "cookie"] as const
    ).map((type) => {
      // FIND TARGET PARAMETERS
      const parameters: OpenApi.IOperation.IParameter[] = (
        props.operation.parameters ?? []
      ).filter((p) => {
        const matches: boolean =
          type === "query"
            ? p.in === "query" || p.in === "querystring"
            : p.in === type;
        return (
          matches &&
          !(
            type === "header" &&
            p.name !== undefined &&
            IGNORED_HEADER_PARAMETERS.has(p.name.toLowerCase())
          )
        );
      });
      if (parameters.length === 0) return null;

      if (type === "query") {
        const querystrings = parameters.filter((p) => p.in === "querystring");
        const queries = parameters.filter((p) => p.in === "query");
        if (querystrings.length > 1) {
          failures.push("querystring parameter must appear at most once");
          return false;
        }
        if (querystrings.length !== 0 && queries.length !== 0) {
          failures.push(
            "querystring parameter cannot coexist with query parameters",
          );
          return false;
        }
      }

      const canonical = (name: string): string =>
        type === "header" ? name.toLowerCase() : name;
      const named = parameters.filter((p) => p.name !== undefined);
      if (named.length !== parameters.length) {
        failures.push(`${type} typed parameters must have a name`);
        return false;
      }
      if (new Set(named.map((p) => canonical(p.name!))).size !== named.length) {
        failures.push(`${type} typed parameter names must be unique`);
        return false;
      }

      const out = (
        elem: {
          schema: OpenApi.IJsonSchema;
          title?: string;
          description?: string;
          example?: any;
          examples?: Record<string, any>;
          querystring?: IHttpMigrateRoute.IQuerystring;
        },
        serializations: IHttpMigrateRoute.ISerialization[],
      ) =>
        ({
          ...elem,
          name: type,
          key: type,
          required: parameters.some((p) => p.required === true),
          parameters: serializations,
          title: () => elem.title,
          description: () => elem.description,
          example: () => elem.example,
          examples: () => elem.examples,
        }) satisfies IHttpMigrateRoute.IHeaders;

      if (
        type === "query" &&
        parameters[0]?.in === "querystring" &&
        parameters[0].content !== undefined
      ) {
        const parameter = parameters[0];
        const entries = Object.entries(parameter.content ?? {}).filter(
          (entry): entry is [string, OpenApi.IOperation.IMediaType] =>
            entry[1] !== undefined,
        );
        if (entries.length !== 1) {
          failures.push(
            "querystring parameter must define exactly one content media type",
          );
          return false;
        }
        const [mediaType, media] = entries[0]!;
        const normalized: string = normalizeMediaType(mediaType);
        const schema: OpenApi.IJsonSchema = resolveSchema(props.document)(
          parameter.schema,
        );
        if (
          normalized === "application/x-www-form-urlencoded" &&
          OpenApiTypeChecker.isObject(schema) === false
        ) {
          failures.push(
            "application/x-www-form-urlencoded querystring parameter requires an object schema",
          );
          return false;
        }
        if (
          normalized !== "application/x-www-form-urlencoded" &&
          isJsonMediaType(normalized) === false &&
          OpenApiTypeChecker.isBoolean(schema) === false &&
          OpenApiTypeChecker.isInteger(schema) === false &&
          OpenApiTypeChecker.isNumber(schema) === false &&
          OpenApiTypeChecker.isString(schema) === false
        ) {
          failures.push(
            `querystring media type ${JSON.stringify(normalized)} requires a scalar schema or JSON representation`,
          );
          return false;
        }
        return out(
          {
            ...parameter,
            schema: sanitizeSchema(props.document)(parameter.schema),
            querystring: {
              type: normalized,
              media: () => media,
            },
          },
          [],
        );
      }

      // CHECK PARAMETER TYPES -> TO BE OBJECT
      const parameterEntries = parameters.map((parameter) => ({
        parameter,
        schema: resolveSchema(props.document)(parameter.schema),
      }));
      const objectParameters = parameterEntries.filter((entry) =>
        OpenApiTypeChecker.isObject(entry.schema),
      ) as {
        parameter: OpenApi.IOperation.IParameter;
        schema: OpenApi.IJsonSchema.IObject;
      }[];
      const primitives = parameterEntries
        .filter((entry) => !OpenApiTypeChecker.isObject(entry.schema))
        .map((entry) => entry.parameter);
      const serialization: IHttpMigrateRoute.ISerialization[] = parameters.map(
        (parameter) => {
          const object = objectParameters.find(
            (entry) => entry.parameter === parameter,
          );
          const schema =
            parameterEntries.find((entry) => entry.parameter === parameter)
              ?.schema ?? parameter.schema;
          const style =
            parameter.style ?? (type === "header" ? "simple" : "form");
          const explode =
            parameter.explode ?? (style === "form" || style === "cookie");
          const allowed =
            type === "header"
              ? style === "simple"
              : type === "cookie"
                ? style === "form" || style === "cookie"
                : [
                    "form",
                    "spaceDelimited",
                    "pipeDelimited",
                    "deepObject",
                  ].includes(style);
          if (allowed === false)
            failures.push(
              `${type} parameter ${JSON.stringify(parameter.name)} does not support ${JSON.stringify(style)} style`,
            );
          if (style === "deepObject") {
            if (object === undefined)
              failures.push(
                `query parameter ${JSON.stringify(parameter.name)} requires an object schema for deepObject style`,
              );
            if (explode === false)
              failures.push(
                `query parameter ${JSON.stringify(parameter.name)} requires explode: true for deepObject style`,
              );
          }
          if (style === "spaceDelimited" || style === "pipeDelimited") {
            if (
              !OpenApiTypeChecker.isArray(schema) &&
              !OpenApiTypeChecker.isTuple(schema) &&
              !OpenApiTypeChecker.isObject(schema)
            )
              failures.push(
                `query parameter ${JSON.stringify(parameter.name)} requires an array or object schema for ${style} style`,
              );
            if (explode)
              failures.push(
                `query parameter ${JSON.stringify(parameter.name)} requires explode: false for ${style} style`,
              );
          }
          return {
            name: parameter.name!,
            key: object === undefined ? parameter.name! : null,
            properties:
              object === undefined
                ? null
                : Object.keys(object.schema.properties ?? {}),
            requiredProperties:
              object === undefined ? null : (object.schema.required ?? []),
            additionalProperties:
              object !== undefined &&
              object.schema.additionalProperties !== false,
            style: style as IHttpMigrateRoute.ISerialization["style"],
            explode,
            parameter: () => parameter,
          };
        },
      );
      if (objectParameters.length === 1 && primitives.length === 0)
        return out(
          sanitizeParameter(props.document)(parameters[0]!),
          serialization,
        );
      else if (objectParameters.length > 1) {
        failures.push(`${type} typed parameters must be only one object type`);
        return false;
      }

      // GATHER TO OBJECT TYPE
      const dto: OpenApi.IJsonSchema.IObject | null =
        objectParameters[0]?.schema ?? null;
      const primitiveNames = new Set(primitives.map((p) => canonical(p.name!)));
      const collisions = Object.keys(dto?.properties ?? {}).filter((name) =>
        primitiveNames.has(canonical(name)),
      );
      if (collisions.length !== 0) {
        failures.push(
          `${type} typed parameter properties conflict: ${collisions.join(", ")}`,
        );
        return false;
      }
      const primitiveProperties: Record<string, OpenApi.IJsonSchema> =
        Object.fromEntries(
          primitives.map((p) => [
            p.name,
            {
              ...p.schema,
              description: p.schema.description ?? p.description,
            },
          ]),
        );
      const primitiveRequired: string[] = primitives
        .filter((p) => p.required)
        .map((p) => p.name!);
      const entire: OpenApi.IJsonSchema.IObject =
        OpenApiSchemaSanitizer.omitEmptyRequired({
          type: "object",
          properties: Object.fromEntries([
            ...Object.entries(primitiveProperties),
            ...(dto ? Object.entries(dto.properties ?? {}) : []),
          ]),
          required: [
            ...new Set([
              ...primitiveRequired,
              ...(objectParameters[0]?.parameter.required
                ? (dto?.required ?? [])
                : []),
            ]),
          ],
          additionalProperties: dto?.additionalProperties,
        });
      const schema: OpenApi.IJsonSchema =
        objectParameters[0] !== undefined &&
        objectParameters[0].parameter.required !== true &&
        (dto?.required?.length ?? 0) !== 0
          ? {
              // Omission is valid, but once an object-owned key is supplied
              // the object's own required fields apply again.
              oneOf: [
                OpenApiSchemaSanitizer.omitEmptyRequired({
                  type: "object",
                  properties: primitiveProperties,
                  required: primitiveRequired,
                  additionalProperties: false,
                }),
                OpenApiSchemaSanitizer.omitEmptyRequired({
                  ...entire,
                  required: [...primitiveRequired, ...(dto?.required ?? [])],
                }),
              ],
            }
          : entire;
      return parameters.length === 0
        ? null
        : out(
            {
              schema: emplaceReference({
                document: props.document,
                name:
                  EndpointUtil.pascal(`I/Api/${props.path}`) +
                  "." +
                  EndpointUtil.pascal(`${props.method}/${type}`),
                schema,
              }),
            },
            serialization,
          );
    });

    //----
    // PATH PARAMETERS
    //----
    const parameterNames: string[] = [
      ...props.path.matchAll(/\{([^{}]+)\}/g),
    ].map((match) => match[1]!);
    const uniqueParameterNames: string[] = [...new Set(parameterNames)];
    const pathParameters: OpenApi.IOperation.IParameter[] = (
      props.operation.parameters ?? []
    ).filter((p) => p.in === "path");
    const duplicatePathNames: string[] = pathParameters
      .map((p) => p.name)
      .filter(
        (name, index, array): name is string =>
          name !== undefined && array.indexOf(name) !== index,
      );
    if (duplicatePathNames.length !== 0)
      failures.push(
        `path parameter names must be unique: ${[...new Set(duplicatePathNames)].join(", ")}`,
      );
    if (
      pathParameters.some(
        (p) => p.name === undefined || !uniqueParameterNames.includes(p.name),
      )
    )
      failures.push("path parameter names are not matched with its full path.");
    else {
      for (const name of uniqueParameterNames)
        if (pathParameters.find((p) => p.name === name) === undefined)
          pathParameters.push({
            name,
            in: "path",
            required: true,
            schema: { type: "string" },
          });
      pathParameters.sort(
        (a, b) =>
          uniqueParameterNames.indexOf(a.name!) -
          uniqueParameterNames.indexOf(b.name!),
      );
      for (const parameter of pathParameters) {
        const style = parameter.style ?? "simple";
        if (!["matrix", "label", "simple"].includes(style))
          failures.push(
            `path parameter ${JSON.stringify(parameter.name)} does not support ${JSON.stringify(style)} style`,
          );
      }
      props.operation.parameters = [
        ...pathParameters,
        ...(props.operation.parameters ?? []).filter((p) => p.in !== "path"),
      ];
    }
    if (failures.length) return failures;

    const usedParameterKeys = new Set<string>();
    const parameters: IHttpMigrateRoute.IParameter[] = pathParameters.map(
      (parameter) => {
        let key: string = EndpointUtil.normalize(parameter.name!).replace(
          /[^a-zA-Z0-9_$]/g,
          "_",
        );
        while (
          NamingConvention.variable(key) === false ||
          usedParameterKeys.has(key)
        )
          key = `_${key}`;
        usedParameterKeys.add(key);
        const style = parameter.style ?? "simple";
        return {
          name: parameter.name!,
          key,
          schema: parameter.schema,
          style: style as IHttpMigrateRoute.IParameter["style"],
          explode: parameter.explode ?? false,
          parameter: () => parameter,
        };
      },
    );
    return {
      method: props.method,
      path: props.path,
      emendedPath: props.emendedPath,
      accessor: ["@lazy"],
      parameters,
      headers: headers || null,
      cookies: cookies || null,
      query: query || null,
      body: body || null,
      success: success || null,
      exceptions: Object.fromEntries(
        Object.entries(props.operation.responses ?? {})
          .filter(([key]) => {
            if (isSuccessStatus(key)) return false;
            return key !== "default" || successResponse?.[0] !== "default";
          })
          .map(([status, response]) => {
            const media = findJsonMedia(response.content);
            const schema =
              media !== undefined
                ? (sanitizeMediaSchema(props.document)(media[1]) ?? {})
                : {};
            return [
              status,
              {
                schema,
                response: () => response,
                media: () =>
                  media?.[1] ?? ({} satisfies OpenApi.IOperation.IMediaType),
              } satisfies IHttpMigrateRoute.IException,
            ];
          }),
      ),
      comment: () =>
        writeRouteComment({
          operation: props.operation,
          parameters,
          query: query || null,
          body: body || null,
        }),
      operation: () => props.operation,
    } satisfies IHttpMigrateRoute as IHttpMigrateRoute;
  };

  const writeRouteComment = (props: {
    operation: OpenApi.IOperation;
    parameters: IHttpMigrateRoute.IParameter[];
    query: IHttpMigrateRoute.IQuery | null;
    body: IHttpMigrateRoute.IBody | null;
  }): string => {
    // write basic description combining with summary
    let description: string = props.operation.description ?? "";
    if (!!props.operation.summary?.length) {
      const summary: string = props.operation.summary.endsWith(".")
        ? props.operation.summary
        : props.operation.summary + ".";
      if (
        !!description.length &&
        !description.startsWith(props.operation.summary)
      )
        description = `${summary}\n\n${description}`;
    }
    description = description
      .split("\n")
      .map((s) => s.trim())
      .join("\n");

    //----
    // compose jsdoc comment tags
    //----
    const commentTags: string[] = [];
    const add = (text: string) => {
      if (commentTags.every((line) => line !== text)) commentTags.push(text);
    };

    // parameters
    add("@param connection");
    for (const p of props.parameters ?? []) {
      const param = p.parameter();
      if (param.description) {
        const text: string = param.description!;
        add(`@param ${p.name} ${writeIndented(text, p.name.length + 8)}`);
      }
    }
    if (props.body?.description()?.length)
      add(`@param body ${writeIndented(props.body.description()!, 12)}`);

    // security
    for (const security of props.operation.security ?? [])
      for (const [name, scopes] of Object.entries(security))
        add(`@security ${[name, ...scopes].join("")}`);

    // categorizing tags
    if (props.operation.tags)
      props.operation.tags.forEach((name) => add(`@tag ${name}`));

    // deprecated
    if (props.operation.deprecated) add("@deprecated");

    // plugin properties
    for (const [key, value] of Object.entries(props.operation)) {
      if (key.startsWith("x-") === false) continue;
      else if (
        value !== null &&
        typeof value !== "boolean" &&
        typeof value !== "number" &&
        typeof value !== "string"
      )
        continue;
      add(`@${key} ${value}`);
    }

    // finalize description
    description = description.length
      ? commentTags.length
        ? `${description}\n\n${commentTags.join("\n")}`
        : description
      : commentTags.join("\n");
    description = description.split("*/").join("*\\/");
    return description;
  };

  const writeIndented = (text: string, spaces: number): string =>
    text
      .split("\n")
      .map((s) => s.trim())
      .map((s, i) => (i === 0 ? s : `${" ".repeat(spaces)}${s}`))
      .join("\n");

  const emplaceBodySchema =
    (document: OpenApi.IDocument) =>
    (from: "request" | "response") =>
    (
      emplacer: (schema: OpenApi.IJsonSchema) => OpenApi.IJsonSchema.IReference,
    ) =>
    (meta?: {
      description?: string;
      content?: Partial<Record<string, OpenApi.IOperation.IMediaType>>; // ISwaggerRouteBodyContent;
      required?: boolean;
      "x-nestia-encrypted"?: boolean;
    }): false | null | IHttpMigrateRoute.IBody => {
      if (!meta?.content) return null;

      const entries: [string, OpenApi.IOperation.IMediaType][] = Object.entries(
        meta.content,
      ).filter(([_, v]) => !!v) as [string, OpenApi.IOperation.IMediaType][];
      const json = entries.find((e) =>
        meta["x-nestia-encrypted"] === true
          ? normalizeMediaType(e[0]) === "text/plain" || isJsonMediaType(e[0])
          : isJsonMediaType(e[0]),
      );
      if (json) {
        const schema = sanitizeMediaSchema(document)(json[1]);
        return schema
          ? {
              type:
                normalizeMediaType(json[0]) === "*/*" ||
                normalizeMediaType(json[0]) === "text/plain"
                  ? "application/json"
                  : (normalizeMediaType(
                      json[0],
                    ) as IHttpMigrateRoute.IBody["type"]),
              name: "body",
              key: "body",
              required: from === "request" && meta.required === true,
              schema: isNotObjectLiteral(schema)
                ? sanitizeSchema(document)(schema)
                : emplacer(schema),
              description: () => meta.description,
              media: () => json[1],
              "x-nestia-encrypted": meta["x-nestia-encrypted"],
            }
          : null;
      }

      const query = entries.find(
        (e) => normalizeMediaType(e[0]) === "application/x-www-form-urlencoded",
      );
      if (query) {
        const schema = sanitizeMediaSchema(document)(query[1]);
        return schema
          ? {
              type: "application/x-www-form-urlencoded",
              name: "body",
              key: "body",
              required: from === "request" && meta.required === true,
              schema: isNotObjectLiteral(schema)
                ? sanitizeSchema(document)(schema)
                : emplacer(schema),
              description: () => meta.description,
              media: () => query[1],
            }
          : null;
      }

      const text = entries.find(
        (e) => normalizeMediaType(e[0]) === "text/plain",
      );
      if (text)
        return {
          type: "text/plain",
          name: "body",
          key: "body",
          required: from === "request" && meta.required === true,
          schema: { type: "string" },
          description: () => meta.description,
          media: () => text[1],
        };

      if (from === "request") {
        const multipart = entries.find(
          (e) => normalizeMediaType(e[0]) === "multipart/form-data",
        );
        if (multipart) {
          const schema = sanitizeMediaSchema(document)(multipart[1]);
          return {
            type: "multipart/form-data",
            name: "body",
            key: "body",
            required: meta.required === true,
            schema: schema
              ? isNotObjectLiteral(schema)
                ? sanitizeSchema(document)(schema)
                : emplacer(schema)
              : {},
            description: () => meta.description,
            media: () => multipart[1],
          };
        }
      }
      return false;
    };

  const sanitizeOperationSchemas =
    (document: OpenApi.IDocument) =>
    (operation: OpenApi.IOperation): void => {
      operation.parameters?.forEach((parameter) => {
        parameter.schema = sanitizeSchema(document)(parameter.schema);
        sanitizeContentSchemas(document)(parameter.content);
      });
      sanitizeContentSchemas(document)(operation.requestBody?.content);
      Object.values(operation.responses ?? {}).forEach((response) =>
        sanitizeContentSchemas(document)(response.content),
      );
    };

  const sanitizeContentSchemas =
    (
      document: OpenApi.IDocument,
    ): ((content: OpenApi.IOperation.IContent | undefined) => void) =>
    (content) => {
      Object.values(content ?? {}).forEach((media) => {
        if (media !== undefined) sanitizeMediaSchema(document)(media);
      });
    };

  const sanitizeMediaSchema =
    (document: OpenApi.IDocument) =>
    (media: OpenApi.IOperation.IMediaType): OpenApi.IJsonSchema | undefined => {
      if (media.schema === undefined) return undefined;
      media.schema = sanitizeSchema(document)(media.schema);
      return media.schema;
    };

  const findJsonMedia = (
    content: OpenApi.IOperation.IContent | undefined,
  ): [string, OpenApi.IOperation.IMediaType] | undefined =>
    Object.entries(content ?? {}).find(
      (entry): entry is [string, OpenApi.IOperation.IMediaType] => {
        const [type, media] = entry;
        return media !== undefined && isJsonMediaType(type);
      },
    );

  /**
   * Store an inline schema as a component named from its route.
   *
   * The name folds `{param}` segments, separators, and letter case, so two
   * routes can derive the same name (`GET /users` and `GET /users/{id}` both
   * derive `IApiUsers.GetResponse`), and the document may already own it.
   * Overwriting made one route silently declare another route's schema (#2451).
   * A taken name is escaped instead, by prefixing `_` to its last segment until
   * it is free, the convention accessors use for duplicates; a route without a
   * collision keeps its name. A name that already holds the very same schema,
   * whatever its key order, is reused, so migrating a migrated document again,
   * which still carries its inline schemas, keeps every name, also after a
   * conversion that reordered their keys.
   */
  const emplaceReference = (props: {
    document: OpenApi.IDocument;
    name: string;
    schema: OpenApi.IJsonSchema;
  }): OpenApi.IJsonSchema.IReference => {
    const schemas: Record<string, OpenApi.IJsonSchema> =
      (props.document.components.schemas ??= {});
    const schema: OpenApi.IJsonSchema = sanitizeSchema(props.document)(
      props.schema,
    );
    const text: string = JsonCanonical.stringify(schema);
    const dot: number = props.name.lastIndexOf(".");
    const namespace: string = props.name.substring(0, dot + 1);
    let member: string = props.name.substring(dot + 1);
    while (
      ObjectDictionary.has(schemas, namespace + member) &&
      JsonCanonical.stringify(schemas[namespace + member]) !== text
    )
      member = `_${member}`;
    const name: string = namespace + member;
    ObjectDictionary.set(schemas, name, schema);
    return {
      $ref: `#/components/schemas/${name}`,
    } satisfies OpenApi.IJsonSchema.IReference;
  };

  const sanitizeParameter =
    (document: OpenApi.IDocument) =>
    (
      parameter: OpenApi.IOperation.IParameter,
    ): OpenApi.IOperation.IParameter => ({
      ...parameter,
      schema: sanitizeSchema(document)(parameter.schema),
    });

  const resolveSchema =
    (document: OpenApi.IDocument) =>
    (input: OpenApi.IJsonSchema): OpenApi.IJsonSchema => {
      let schema: OpenApi.IJsonSchema = input;
      const visited: Set<string> = new Set();
      while (OpenApiTypeChecker.isReference(schema)) {
        const entry = OpenApiReferenceKey.find(
          document.components.schemas,
          schema.$ref,
          SCHEMAS,
        );
        if (entry === undefined || visited.has(entry.key)) break;
        visited.add(entry.key);
        schema = entry.value;
      }
      return schema;
    };

  const sanitizeSchema =
    (document: OpenApi.IDocument) =>
    (schema: OpenApi.IJsonSchema): OpenApi.IJsonSchema => {
      const visited: Set<string> = new Set();
      return sanitizeSchemaRecursively(document)(visited)(schema);
    };

  const sanitizeSchemaRecursively =
    (document: OpenApi.IDocument) =>
    (visited: Set<string>) =>
    (schema: OpenApi.IJsonSchema): OpenApi.IJsonSchema => {
      if (OpenApiTypeChecker.isReference(schema)) {
        // WRITE BACK UNDER THE KEY THE COMPONENT WAS FOUND BY
        const entry = OpenApiReferenceKey.find(
          document.components.schemas,
          schema.$ref,
          SCHEMAS,
        );
        if (entry !== undefined && visited.has(entry.key) === false) {
          visited.add(entry.key);
          ObjectDictionary.set(
            document.components.schemas!,
            entry.key,
            sanitizeSchemaRecursively(document)(visited)(entry.value),
          );
        }
        return schema;
      }
      const sanitized: OpenApi.IJsonSchema =
        OpenApiSchemaSanitizer.omitEmptyRequiredDeep(schema);
      visitSchemaReferences(document)(visited)(sanitized);
      return sanitized;
    };

  const visitSchemaReferences =
    (document: OpenApi.IDocument) =>
    (visited: Set<string>) =>
    (schema: OpenApi.IJsonSchema): void => {
      const visit = sanitizeSchemaRecursively(document)(visited);
      if (OpenApiTypeChecker.isOneOf(schema))
        schema.oneOf.forEach((value) => visit(value));
      else if (OpenApiTypeChecker.isTuple(schema)) {
        schema.prefixItems.forEach((value) => visit(value));
        if (
          typeof schema.additionalItems === "object" &&
          schema.additionalItems !== null
        )
          visit(schema.additionalItems);
      } else if (OpenApiTypeChecker.isArray(schema)) visit(schema.items);
      else if (OpenApiTypeChecker.isObject(schema)) {
        Object.values(schema.properties ?? {}).forEach((value) => visit(value));
        if (
          typeof schema.additionalProperties === "object" &&
          schema.additionalProperties !== null
        )
          visit(schema.additionalProperties);
      }
    };

  const isNotObjectLiteral = (schema: OpenApi.IJsonSchema): boolean =>
    OpenApiTypeChecker.isReference(schema) ||
    OpenApiTypeChecker.isBoolean(schema) ||
    OpenApiTypeChecker.isNumber(schema) ||
    OpenApiTypeChecker.isString(schema) ||
    OpenApiTypeChecker.isUnknown(schema) ||
    (OpenApiTypeChecker.isOneOf(schema) &&
      schema.oneOf.every(isNotObjectLiteral)) ||
    (OpenApiTypeChecker.isArray(schema) && isNotObjectLiteral(schema.items));

  const normalizeMediaType = (type: string): string =>
    type.split(";", 1)[0]!.trim().toLowerCase();

  const isJsonMediaType = (type: string): boolean => {
    const normalized: string = normalizeMediaType(type);
    return (
      normalized === "application/json" ||
      normalized.endsWith("+json") ||
      normalized === "*/*"
    );
  };
}

const isSuccessStatus = (status: string): boolean =>
  /^2\d\d$/.test(status) || /^2xx$/i.test(status);

const selectSuccessResponse = (
  responses: Record<string, OpenApi.IOperation.IResponse> | undefined,
): [string, OpenApi.IOperation.IResponse] | undefined => {
  const entries = Object.entries(responses ?? {}).filter(([status]) =>
    isSuccessStatus(status),
  );
  entries.sort(([x], [y]) => {
    const priority = (status: string): number =>
      status === "200"
        ? 0
        : status === "201"
          ? 1
          : /^2\d\d$/.test(status)
            ? Number(status)
            : 300;
    return priority(x) - priority(y) || x.localeCompare(y);
  });
  return (
    entries[0] ??
    (responses?.default ? (["default", responses.default] as const) : undefined)
  );
};

const IGNORED_HEADER_PARAMETERS = new Set([
  "accept",
  "authorization",
  "content-type",
]);

import { IHttpMigrateRoute, IHttpResponse } from "@typia/interface";

import { HttpError } from "../HttpError";
import type { HttpMigration } from "../HttpMigration";

/**
 * Performs the HTTP request that a migrated route describes.
 *
 * The caller's arguments are checked against the route, serialized by the
 * OpenAPI style rules of each parameter group, and sent through the
 * connection's `fetch` or the global one.
 *
 * @evidence contracts/common.md#principled-implementation The request is built by checking the arguments against the route's groups, serializing path, query, header and cookie values by their OpenAPI style, encoding the body by media type and sending it through the connection's fetch or the global one; the response body is parsed by content type. Non-2xx responses are thrown only by execute.
 * @evidence contracts/common.md#clear-and-simple-design Two exported functions over one private request function; serialization, parsing and encoding helpers are module-level because they are used by the request builder only.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The connection fetch is the supported replacement point, and no global is patched.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment and function docs cover the request, serialization and error contract.
 */
export namespace HttpMigrateRouteFetcher {
  /**
   * Send the request and return the body of a 2xx response.
   *
   * @param props Route, connection and arguments
   *
   * @returns Parsed response body
   *
   * @throws HttpError on a non-2xx status, and Error when the arguments do not
   *   match the route
   *
   * @evidence contracts/common.md#principled-implementation It awaits the propagated response and throws HttpError for any status outside 200 to 299, marking the body as already parsed so the error does not reparse it, and otherwise returns the body.
   * @evidence contracts/common.md#clear-and-simple-design A short function over propagateRequest.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Status handling is only the range check.
   * @evidence contracts/common.md#meaningful-documentation The doc states the body, the thrown errors and the parameter.
   */
  export const execute = async (
    props: HttpMigration.IFetchProps,
  ): Promise<unknown> => {
    const result: IHttpResponse = await propagateRequest("request", props);
    if (result.status < 200 || result.status >= 300)
      throw new HttpError(
        props.route.method.toUpperCase() as "GET",
        props.route.path,
        result.status,
        result.headers,
        result.body,
        true,
      );
    return result.body;
  };

  /**
   * Send the request and return the whole response.
   *
   * @param props Route, connection and arguments
   *
   * @returns Status, headers and parsed body, including non-2xx responses
   *
   * @throws Error when the arguments do not match the route, or when request
   *   serialization, the connection or response parsing fails
   *
   * @evidence contracts/common.md#principled-implementation It returns the response of the shared request function without a status check, so every status is data. Argument checks, request serialization, the connection and response parsing can still throw.
   * @evidence contracts/common.md#clear-and-simple-design A one-line delegation.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It adds no behavior beyond the request function.
   * @evidence contracts/common.md#meaningful-documentation The doc states the full response and the thrown errors.
   */
  export const propagate = (
    props: HttpMigration.IFetchProps,
  ): Promise<IHttpResponse> => propagateRequest("propagate", props);
}

const propagateRequest = async (
  from: string,
  props: HttpMigration.IFetchProps,
): Promise<IHttpResponse> => {
  const error = (message: string) =>
    new Error(`Error on MigrateRouteFetcher.${from}(): ${message}`);
  if (Array.isArray(props.parameters)) {
    if (props.route.parameters.length !== props.parameters.length)
      throw error(`number of parameters is not matched.`);
  } else {
    const parameters = props.parameters;
    if (
      props.route.parameters.every(
        (parameter) => parameters[parameter.key] !== undefined,
      ) === false
    )
      throw error(`number of parameters is not matched.`);
  }

  validateGroup(error)("headers", props.route.headers, props.headers);
  validateGroup(error)("cookies", props.route.cookies ?? null, props.cookies);
  validateGroup(error)(
    "query",
    props.route.query,
    props.query,
    props.route.query?.querystring === undefined,
  );
  validateBody(error)(props.route.body, props.body);

  const headers: Headers = requestHeaders(error)(props);
  const init: RequestInit = {
    ...(props.connection.options ?? {}),
    method: props.route.method.toUpperCase(),
    headers,
  };
  if (props.body !== undefined)
    init.body = (
      props.route.body?.type === "application/x-www-form-urlencoded"
        ? requestQueryBody(props.body as object)
        : props.route.body?.type === "multipart/form-data"
          ? requestFormDataBody(props.body as Record<string, any>)
          : isJsonMediaType(props.route.body?.type)
            ? JSON.stringify(props.body)
            : props.body
    ) as BodyInit;

  const path: string = getPath(error, props);
  const host: string = props.connection.host;
  const joined: string =
    host.endsWith("/") && path.startsWith("/")
      ? host + path.substring(1)
      : !host.endsWith("/") && !path.startsWith("/")
        ? `${host}/${path}`
        : host + path;
  const response: Response = await (props.connection.fetch ?? fetch)(
    new URL(joined),
    init,
  );
  const out = (body: unknown): IHttpResponse => ({
    status: response.status,
    headers: responseHeaders(response.headers),
    body,
  });

  if (response.status >= 200 && response.status < 300) {
    if (
      props.route.method === "head" ||
      response.status === 204 ||
      response.status === 205
    )
      return out(undefined);
    return out(
      await parseResponseBody(
        response,
        contentType(response.headers) ||
          props.route.success?.type ||
          "text/plain",
      ),
    );
  }
  const type: string = contentType(response.headers);
  return out(await parseResponseBody(response, type));
};

const validateGroup =
  (error: (message: string) => Error) =>
  (
    name: string,
    metadata:
      | IHttpMigrateRoute.IHeaders
      | IHttpMigrateRoute.IQuery
      | IHttpMigrateRoute.ICookies
      | IHttpMigrateRoute.IBody
      | null,
    input: unknown,
    objectOnly: boolean = true,
  ): void => {
    if (metadata === null) {
      if (input !== undefined) throw error(`${name} is not matched.`);
      return;
    }
    if ((metadata.required ?? true) && input === undefined)
      throw error(`${name} is not matched.`);
    if (
      objectOnly &&
      input !== undefined &&
      (typeof input !== "object" || input === null || Array.isArray(input))
    )
      throw error(`${name} must be an object.`);
  };

const validateBody =
  (error: (message: string) => Error) =>
  (metadata: IHttpMigrateRoute.IBody | null, input: unknown): void => {
    if (metadata === null) {
      if (input !== undefined) throw error(`body is not matched.`);
      return;
    }
    if ((metadata.required ?? true) && input === undefined)
      throw error(`body is not matched.`);
    if (
      input !== undefined &&
      (metadata.type === "application/x-www-form-urlencoded" ||
        metadata.type === "multipart/form-data") &&
      (typeof input !== "object" || input === null || Array.isArray(input))
    )
      throw error(`body must be an object for ${metadata.type}.`);
  };

const requestHeaders =
  (error: (message: string) => Error) =>
  (props: HttpMigration.IFetchProps): Headers => {
    const output = new Headers();
    for (const [key, value] of Object.entries(props.connection.headers ?? {}))
      if (value === undefined) continue;
      else if (Array.isArray(value))
        value.forEach((elem) => output.append(key, String(elem)));
      else output.append(key, String(value));

    if (props.route.headers && props.headers) {
      const parameters = props.route.headers.parameters;
      if (parameters === undefined) {
        for (const [key, value] of Object.entries(props.headers))
          if (value !== undefined)
            output.set(key, serializeSimple(value, false));
      } else {
        const serializations: IHttpMigrateRoute.ISerialization[] = parameters;
        for (const metadata of serializations) {
          const value = parameterValue(metadata, props.headers, serializations);
          if (value === undefined) {
            if (metadata.parameter().required)
              throw error(
                `header ${JSON.stringify(metadata.name)} is required.`,
              );
            continue;
          }
          output.set(metadata.name, serializeSimple(value, metadata.explode));
        }
      }
    }

    if (props.route.cookies && props.cookies) {
      const parameters = props.route.cookies.parameters;
      const supplied =
        parameters === undefined
          ? Object.entries(props.cookies).flatMap(([name, value]) =>
              value === undefined ? [] : serializeCookie(name, value, true),
            )
          : parameters.flatMap((metadata) => {
              const value = parameterValue(
                metadata,
                props.cookies!,
                parameters,
              );
              if (value === undefined) {
                if (metadata.parameter().required)
                  throw error(
                    `cookie ${JSON.stringify(metadata.name)} is required.`,
                  );
                return [];
              }
              return serializeCookie(
                metadata.name,
                value,
                metadata.explode,
                metadata.style,
              );
            });
      if (supplied.length !== 0) {
        const replaced = new Set(supplied.map(([name]) => name));
        const inherited = (output.get("cookie") ?? "")
          .split(";")
          .map((part) => part.trim())
          .filter((part) => part.length !== 0)
          .filter((part) => !replaced.has(part.split("=", 1)[0]!));
        output.set(
          "Cookie",
          [...inherited, ...supplied.map(([name, value]) => `${name}=${value}`)]
            .filter((part) => part.length !== 0)
            .join("; "),
        );
      }
    }

    if (props.body !== undefined && props.route.body?.type)
      if (props.route.body.type === "multipart/form-data")
        output.delete("Content-Type");
      else output.set("Content-Type", props.route.body.type);
    return output;
  };

const getPath = (
  error: (message: string) => Error,
  props: Pick<HttpMigration.IFetchProps, "route" | "parameters" | "query">,
): string => {
  const byName = new Map(
    props.route.parameters.map((parameter, index) => [
      parameter.name,
      {
        parameter,
        value: Array.isArray(props.parameters)
          ? props.parameters[index]
          : props.parameters[parameter.key],
      },
    ]),
  );
  let path: string =
    // Preserve legacy/custom emended static paths, while parameterized paths
    // use source expressions so embedded and repeated names stay unambiguous.
    props.route.parameters.length === 0
      ? props.route.emendedPath
      : props.route.path.replace(
          /\{([^{}]+)\}/g,
          (expression, name: string) => {
            const found = byName.get(name);
            return found === undefined
              ? expression
              : serializePath(found.parameter, found.value);
          },
        );
  if (props.route.query && props.query !== undefined)
    path +=
      props.route.query.querystring !== undefined
        ? getQuerystringPath(error, props.route.query, props.query)
        : getQueryPath(error, props.route.query, props.query as object);
  return path;
};

const getQuerystringPath = (
  error: (message: string) => Error,
  route: IHttpMigrateRoute.IQuery,
  query: unknown,
): string => {
  const type: string = route.querystring!.type;
  let serialized: string;
  if (type === "application/x-www-form-urlencoded") {
    if (!isRecord(query)) throw error(`query must be an object for ${type}.`);
    serialized = requestQueryBody(query).toString();
  } else if (isJsonMediaType(type)) {
    const value: string | undefined = JSON.stringify(query);
    if (value === undefined)
      throw error(`query cannot be serialized as ${type}.`);
    serialized = encodeRfc3986(value);
  } else {
    if (typeof query === "object" && query !== null)
      throw error(`query must be a scalar for ${type}.`);
    serialized = encodeRfc3986(query);
  }
  return serialized.length === 0 ? "" : `?${serialized}`;
};

const getQueryPath = (
  error: (message: string) => Error,
  route: IHttpMigrateRoute.IQuery,
  query: object,
): string => {
  if (route.parameters === undefined) {
    const variables = new URLSearchParams();
    for (const [key, value] of Object.entries(query))
      if (value === undefined) continue;
      else if (Array.isArray(value))
        value.forEach((elem) => variables.append(key, String(elem)));
      else variables.set(key, String(value));
    return variables.size === 0 ? "" : `?${variables.toString()}`;
  }
  const variables: string[] = [];
  for (const metadata of route.parameters) {
    const value = parameterValue(metadata, query, route.parameters);
    if (value === undefined) {
      if (metadata.parameter().required)
        throw error(`query ${JSON.stringify(metadata.name)} is required.`);
      continue;
    }
    variables.push(...serializeQuery(metadata, value));
  }
  return variables.length === 0 ? "" : `?${variables.join("&")}`;
};

const parameterValue = (
  metadata: IHttpMigrateRoute.ISerialization,
  input: object,
  parameters: IHttpMigrateRoute.ISerialization[],
): unknown => {
  const record = input as Record<string, unknown>;
  if (metadata.key !== null) return record[metadata.key];
  const properties = new Set(metadata.properties ?? []);
  const occupied = new Set(
    parameters
      .filter((parameter) => parameter !== metadata)
      .flatMap((parameter) =>
        parameter.key !== null ? [parameter.key] : (parameter.properties ?? []),
      ),
  );
  const entries = Object.entries(record).filter(
    ([key, value]) =>
      value !== undefined &&
      (properties.has(key) ||
        (metadata.additionalProperties === true && !occupied.has(key))),
  );
  return entries.length !== 0 ||
    (metadata.properties?.length ?? 0) === 0 ||
    (metadata.parameter().required === true &&
      metadata.requiredProperties?.length === 0)
    ? Object.fromEntries(entries)
    : undefined;
};

const serializeQuery = (
  metadata: IHttpMigrateRoute.ISerialization,
  value: unknown,
): string[] => {
  const encode = encodeRfc3986;
  const name: string = encode(metadata.name);
  const pair = (key: unknown, elem: unknown): string =>
    `${encode(key)}=${encode(elem)}`;
  if (metadata.style === "deepObject")
    return objectEntries(value).map(
      ([key, elem]) => `${name}%5B${encode(key)}%5D=${encode(elem)}`,
    );
  if (
    metadata.style === "spaceDelimited" ||
    metadata.style === "pipeDelimited"
  ) {
    const delimiter = metadata.style === "spaceDelimited" ? "%20" : "%7C";
    return [
      `${name}=${
        isRecord(value)
          ? objectEntries(value)
              .flatMap(([key, elem]) => [encode(key), encode(elem)])
              .join(delimiter)
          : arrayValues(value).map(encode).join(delimiter)
      }`,
    ];
  }
  if (Array.isArray(value))
    return metadata.explode
      ? value.map((elem) => `${name}=${encode(elem)}`)
      : [`${name}=${value.map(encode).join(",")}`];
  if (isRecord(value)) {
    const entries = objectEntries(value);
    return metadata.explode
      ? entries.map(([key, elem]) => pair(key, elem))
      : [
          `${name}=${entries
            .flatMap(([key, elem]) => [encode(key), encode(elem)])
            .join(",")}`,
        ];
  }
  return [`${name}=${encode(value)}`];
};

const serializePath = (
  metadata: IHttpMigrateRoute.IParameter,
  value: unknown,
): string => {
  const encode = encodeRfc3986;
  const name: string = encode(metadata.name);
  const style = metadata.style ?? "simple";
  const explode = metadata.explode ?? false;
  const array = Array.isArray(value) ? value.map(encode) : null;
  const object = isRecord(value)
    ? objectEntries(value).map(([key, elem]) => [encode(key), encode(elem)])
    : null;
  if (style === "matrix") {
    if (array)
      return explode
        ? array.map((elem) => `;${name}=${elem}`).join("")
        : `;${name}=${array.join(",")}`;
    if (object)
      return explode
        ? object.map(([key, elem]) => `;${key}=${elem}`).join("")
        : `;${name}=${object.flat().join(",")}`;
    return `;${name}=${encode(value)}`;
  }
  if (style === "label") {
    if (array) return `.${array.join(explode ? "." : ",")}`;
    if (object)
      return `.${
        explode
          ? object.map(([key, elem]) => `${key}=${elem}`).join(".")
          : object.flat().join(",")
      }`;
    return `.${encode(value)}`;
  }
  if (array) return array.join(",");
  if (object)
    return explode
      ? object.map(([key, elem]) => `${key}=${elem}`).join(",")
      : object.flat().join(",");
  return encode(value);
};

const serializeSimple = (value: unknown, explode: boolean): string => {
  if (Array.isArray(value)) return value.map(String).join(",");
  if (isRecord(value)) {
    const entries = objectEntries(value);
    return explode
      ? entries.map(([key, elem]) => `${key}=${String(elem)}`).join(",")
      : entries.flatMap(([key, elem]) => [key, String(elem)]).join(",");
  }
  return String(value);
};

const serializeCookie = (
  name: string,
  value: unknown,
  explode: boolean,
  style: IHttpMigrateRoute.ISerialization["style"] = "form",
): [string, string][] => {
  const encode = (input: unknown): string =>
    style === "cookie" ? String(input) : encodeRfc3986(input);
  const encodedName: string = encode(name);
  if (Array.isArray(value))
    return explode
      ? value.map((elem) => [encodedName, encode(elem)])
      : [[encodedName, value.map(encode).join(",")]];
  if (isRecord(value)) {
    const entries = objectEntries(value);
    return explode
      ? entries.map(([key, elem]) => [encode(key), encode(elem)])
      : [
          [
            encodedName,
            entries
              .flatMap(([key, elem]) => [encode(key), encode(elem)])
              .join(","),
          ],
        ];
  }
  return [[encodedName, encode(value)]];
};

const requestQueryBody = (input: object): URLSearchParams => {
  const output = new URLSearchParams();
  for (const [key, value] of Object.entries(input))
    if (value === undefined) continue;
    else if (Array.isArray(value))
      value.forEach((elem) => output.append(key, String(elem)));
    else output.set(key, String(value));
  return output;
};

const requestFormDataBody = (input: Record<string, any>): FormData => {
  const output = new FormData();
  const append = (key: string) => (value: any) => {
    if (value === undefined) return;
    if (typeof File === "function" && value instanceof File)
      output.append(key, value, value.name);
    else output.append(key, value);
  };
  for (const [key, value] of Object.entries(input))
    if (Array.isArray(value)) value.forEach(append(key));
    else append(key)(value);
  return output;
};

const contentType = (headers: Headers): string =>
  (headers.get("content-type") ?? "").split(";", 1)[0]!.trim().toLowerCase();

const isJsonMediaType = (type: string | undefined): boolean => {
  const normalized: string = (type ?? "")
    .split(";", 1)[0]!
    .trim()
    .toLowerCase();
  return normalized === "application/json" || normalized.endsWith("+json");
};

const parseResponseBody = async (
  response: Response,
  type: string,
): Promise<unknown> => {
  if (type === "application/json" || type.endsWith("+json")) {
    const text: string = await response.text();
    return text.length === 0 ? undefined : JSON.parse(text);
  }
  if (type === "application/x-www-form-urlencoded")
    return new URLSearchParams(await response.text());
  if (type === "multipart/form-data") return response.formData();
  if (type === "application/octet-stream") return response.blob();
  return response.text();
};

const responseHeaders = (
  headers: Headers,
): Record<string, string | string[]> => {
  const output: Record<string, string | string[]> = {};
  headers.forEach((value, key) => {
    if (key !== "set-cookie") output[key] = value;
  });
  const getter = (
    headers as Headers & {
      getSetCookie?: () => string[];
    }
  ).getSetCookie;
  const cookies: string[] =
    typeof getter === "function"
      ? getter.call(headers)
      : headers.get("set-cookie") !== null
        ? [headers.get("set-cookie")!]
        : [];
  if (cookies.length !== 0) output["set-cookie"] = cookies;
  return output;
};

const arrayValues = (value: unknown): unknown[] =>
  Array.isArray(value) ? value : [value];

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const objectEntries = (value: unknown): [string, unknown][] =>
  isRecord(value)
    ? Object.entries(value).filter((entry) => entry[1] !== undefined)
    : [];

const encodeRfc3986 = (input: unknown): string =>
  encodeURIComponent(String(input)).replace(
    /[!'()*]/g,
    (character) => `%${character.charCodeAt(0).toString(16).toUpperCase()}`,
  );

