  const coversUpperBoundary = (
    x: IBoundary | null,
    y: IBoundary | null,
  ): boolean =>
    x === null ||
    (y !== null &&
      (y.value < x.value ||
        (y.value === x.value && (x.exclusive === false || y.exclusive))));
