          (s: ILlmSchema): boolean =>
            LlmTypeChecker.isBoolean(resolveSchema(s, $defs)),
        );
        const hasNull: boolean = schema.anyOf.some((s: ILlmSchema): boolean =>
          LlmTypeChecker.isNull(resolveSchema(s, $defs)),
