  try {
    return iterate(input);
  } catch {
    // actually unreachable, maybe?
    return {
      success: false,
      data: undefined as DeepPartial<T>,
      input,
      errors: [
        {
          path: "$input",
          expected: "valid JSON",
          description: error.message,
        },
      ],
    };
  }
}

function iterate<T>(input: string): IJsonParseResult<T> {
